"""Explicit uncertainty and object identity shared by both language adapters."""
from dataclasses import dataclass, field
from decimal import Decimal
import math
import operator


@dataclass(frozen=True)
class Unknown:
    reason: str
    typ: str = ""
    origin: str = ""

    def __bool__(self):
        raise TypeError("Unknown must be branched explicitly")


@dataclass(frozen=True)
class Symbol:
    identity: str
    typ: str
    nonnull: bool = True
    sort: str = ""


@dataclass(frozen=True)
class Formula:
    op: str
    args: tuple
    sort: str
    language: str


@dataclass(frozen=True)
class Text:
    """A string with symbolic pieces; it is never mistaken for concrete bytes."""
    parts: tuple


@dataclass
class Object:
    identity: str
    typ: str
    fields: dict = field(default_factory=dict)
    provided: set | None = None


@dataclass(frozen=True)
class TypeRef:
    name: str


@dataclass(frozen=True)
class FunctionRef:
    name: str


@dataclass
class Awaitable:
    method: str
    args: tuple
    kwargs: dict
    receiver: object = None
    span: object = None
    library: bool = False


@dataclass
class Response:
    body: object = None
    status: object = 200
    headers: dict = field(default_factory=dict)


@dataclass(frozen=True)
class Predicate:
    field: str
    op: str
    value: object


@dataclass
class Query:
    entity: str
    predicates: list = field(default_factory=list)
    offset: int = 0
    limit: int | None = None
    count: bool = False
    delete: bool = False


class Raised(Exception):
    def __init__(self, typ, value=None):
        super().__init__(typ)
        self.typ, self.value = typ, value


def unknown(value):
    return isinstance(value, (Unknown, Symbol, Text, Formula))


def symbolic(value):
    return isinstance(value, (Symbol, Formula)) and value.sort in {"bool", "int", "bv32", "bv64"}


def formula(op, left, right, language, typ=""):
    if not (symbolic(left) or symbolic(right)):
        return None
    if not all(symbolic(value) or type(value) in {int, bool} for value in (left, right)):
        return None
    comparisons = {"==", "!=", ">", "<", ">=", "<="}
    operations = comparisons | {"+", "-", "*", "//", "%", "&", "|", "^", "<<", ">>"}
    if language == "java":
        operations.add("/")
    if op not in operations:
        return None
    if any(getattr(value, "sort", "") == "bool" for value in (left, right)) and op not in {"==", "!="}:
        return None
    sort = "bool" if op in comparisons else "bv64" if language == "java" and (typ in {"long", "Long"} or any(getattr(v, "sort", "") == "bv64" for v in (left, right))) else "bv32" if language == "java" else "int"
    return Formula(op, (left, right), sort, language)


def truth(value, language="python"):
    if isinstance(value, (Unknown, Text, Formula)):
        return None
    if isinstance(value, Symbol):
        return None
    if language == "java":
        return value if type(value) is bool else None
    return bool(value)


def equal(left, right):
    symbolic_result = formula("==", left, right, "python")
    if symbolic_result is not None:
        return symbolic_result
    if isinstance(left, (Unknown, Text)) or isinstance(right, (Unknown, Text)):
        return Unknown("comparison depends on unknown value", "bool")
    if isinstance(left, Symbol) or isinstance(right, Symbol):
        if left == right:
            return True
        if left is None or right is None:
            symbol = right if left is None else left
            if isinstance(symbol, Symbol) and symbol.nonnull:
                return False
        return Unknown("symbolic equality", "bool")
    if isinstance(left, Object) or isinstance(right, Object):
        if isinstance(left, Object) and isinstance(right, Object):
            return left.identity == right.identity
        return False
    return left == right


def integer(value, typ):
    widths = {"byte": 8, "short": 16, "int": 32, "Integer": 32, "long": 64, "Long": 64}
    if type(value) is int and typ in widths:
        bits = widths[typ]
        return (value + (1 << (bits - 1))) % (1 << bits) - (1 << (bits - 1))
    if symbolic(value) and typ in widths:
        # Narrow casts are sign-extended back to the Java arithmetic width.
        return Formula("cast:" + str(widths[typ]), (value,), "bv64" if widths[typ] == 64 else "bv32", "java")
    return value


def binary(op, left, right, language, typ=""):
    if isinstance(left, TypeRef) and op in {"==", "!=", ">", "<", ">=", "<="}:
        return Predicate(left.name, op, right)
    if op in {"/", "//", "%"} and type(right) is int and right == 0 and (type(left) is int or symbolic(left)):
        raise Raised("ArithmeticException" if language == "java" else "ZeroDivisionError")
    symbolic_result = formula(op, left, right, language, typ)
    if symbolic_result is not None:
        return symbolic_result
    if op in {"==", "is", "!=", "is not"}:
        result = equal(left, right)
        return (not result if op in {"!=", "is not"} else result) if type(result) is bool else result
    if op == "+" and (isinstance(left, Text) or isinstance(right, Text) or
                       language == "java" and (isinstance(left, str) or isinstance(right, str))):
        if isinstance(left, Unknown) or isinstance(right, Unknown):
            return Unknown("unknown string operand", "str")
        if isinstance(left, (Text, Symbol)) or isinstance(right, (Text, Symbol)):
            def pieces(value):
                return value.parts if isinstance(value, Text) else (value if isinstance(value, (str, Symbol)) else str(value),)
            return Text(pieces(left) + pieces(right))
    if unknown(left) or unknown(right):
        return Unknown("unknown operand: " + op, typ)
    if op == "+" and language == "java" and (isinstance(left, str) or isinstance(right, str)):
        def string(v):
            return "null" if v is None else str(v).lower() if type(v) is bool else str(v)
        return string(left) + string(right)
    if (left is None or right is None) and language == "java":
        raise Raised("NullPointerException")
    if language == "java" and op in {"/", "%"} and type(left) is int and type(right) is int:
        if right == 0:
            raise Raised("ArithmeticException")
        quotient = (abs(left) // abs(right)) * (-1 if (left < 0) != (right < 0) else 1)
        return integer(quotient if op == "/" else left - quotient * right, typ or "int")
    operations = {"+": operator.add, "-": operator.sub, "*": operator.mul, "/": operator.truediv,
                  "//": operator.floordiv, "%": operator.mod, "**": operator.pow,
                  ">": operator.gt, "<": operator.lt, ">=": operator.ge, "<=": operator.le,
                  "in": lambda a, b: a in b, "not in": lambda a, b: a not in b,
                  "&": operator.and_, "|": operator.or_, "^": operator.xor,
                  "<<": operator.lshift, ">>": operator.rshift}
    if op not in operations:
        return Unknown("unsupported binary operator " + op, typ)
    try:
        result = operations[op](left, right)
        return integer(result, typ or "int") if language == "java" else result
    except (ValueError, TypeError, IndexError, ZeroDivisionError, OverflowError) as exc:
        raise Raised(type(exc).__name__) from None


def wire(value):
    if isinstance(value, Object):
        return {k: wire(v) for k, v in value.fields.items()}
    if isinstance(value, dict):
        return {k: wire(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [wire(v) for v in value]
    return value


def serial(value):
    if isinstance(value, Decimal):
        return {"kind": "Decimal", "value": str(value)}
    if isinstance(value, (Unknown, Symbol, Text, Object, TypeRef, FunctionRef, Awaitable, Response, Query, Predicate)):
        return {"kind": type(value).__name__, **{k: serial(v) for k, v in vars(value).items()}}
    if hasattr(value, "__dataclass_fields__"):
        return {"kind": type(value).__name__, **{k: serial(v) for k, v in vars(value).items()}}
    if isinstance(value, dict):
        return {str(k): serial(v) for k, v in value.items()}
    if isinstance(value, set):
        return [serial(v) for v in sorted(value, key=str)]
    if isinstance(value, (list, tuple)):
        return [serial(v) for v in value]
    if isinstance(value, float) and not math.isfinite(value):
        return {"kind": "Unknown", "reason": "nonfinite JSON number"}
    return value

"""One bounded evaluator for both frontends. No Java/Python parser dependencies."""
from dataclasses import dataclass
from copy import deepcopy
import re

from .ir import Span
from .state import State
from .constraints import PathSolver
from .values import (Awaitable, Formula, FunctionRef, Object, Predicate, Raised, Response, Symbol,
                     Text, TypeRef, Unknown, binary, equal, integer, serial, symbolic, truth, unknown)

GLOBAL_NAMES = object()
SCOPES = object()


class BranchPoint(Exception):
    def __init__(self, position, choices, label):
        self.position, self.choices, self.label = position, choices, label


class Incomplete(Exception):
    pass


class Infeasible(Exception):
    pass


@dataclass
class Completion:
    kind: str = "normal"
    value: object = None


class Kernel:
    def __init__(self, project, state=None, decisions=(), loop_limit=32, depth_limit=32, step_limit=30000, context=None, smt=True, smt_timeout_ms=50):
        self.p, self.state = project, state if state is not None else State()
        self.decisions, self.choice_position = decisions, 0
        self.loop_limit, self.depth_limit, self.step_limit = loop_limit, depth_limit, step_limit
        self.context = context or {}
        self.frames, self.edges, self.diagnostics, self.events = [], {}, [], []
        self.operations, self.partial, self.last_exception = 0, False, None
        self.dependency_cache = {}
        self.resolving_dependencies = set()
        self.unknown_teardown = False
        self.initialization_language = ""
        self.solver = PathSolver(smt, smt_timeout_ms)

    @property
    def method(self):
        return self.frames[-1][0] if self.frames else None

    @property
    def language(self):
        return self.initialization_language or (self.method.language if self.method else "python")

    def note(self, code, message, span=Span(), **detail):
        self.partial = True
        record = {"code": code, "message": message, "file": span.file, "line": span.line, **serial(detail)}
        if record not in self.diagnostics:
            self.diagnostics.append(record)

    def tick(self, span):
        self.operations += 1
        if self.operations > self.step_limit:
            self.note("operation-budget", "Operation budget exhausted; remaining effects unknown", span)
            raise Incomplete()

    def choose(self, choices, label):
        position = self.choice_position
        self.choice_position += 1
        if position >= len(self.decisions):
            raise BranchPoint(position, tuple(choices), label)
        selected = self.decisions[position]
        if selected not in choices:
            raise ValueError("Invalid replay decision")
        return selected

    def condition(self, value, span):
        if isinstance(value, Predicate):
            self.note("predicate-as-boolean", "A symbolic field predicate is not a concrete condition", span)
            value = Unknown("symbolic predicate outside query evaluation", "boolean")
        if isinstance(value, Object) and self.language == "python" and value.typ in self.p.types:
            for special in ["__bool__", "__len__"]:
                methods = self.p.methods_of(value.typ, special, 0)
                if len(methods) == 1:
                    value = self.execute_method(methods[0].key, receiver=value, span=span)
                    break
        result = truth(value, self.language)
        if result is None:
            choices, predicate = self.solver.outcomes(value) if symbolic(value) else ((False, True), None)
            if not choices:
                raise Infeasible()
            if len(choices) == 1:
                self.events.append({"kind": "solver-forced-condition", "file": span.file, "line": span.line, "outcome": choices[0], "value": value})
                selected = choices[0]
            else:
                self.note("unknown-condition", "Both feasible or unproved outcomes are considered", span, value=value)
                selected = self.choose(choices, f"{span.file}:{span.line}:condition")
            self.solver.assume(predicate, selected)
            return selected
        return result

    def add(self, source, relation, target, span=Span(), reason="source semantics"):
        if not source or not target:
            self.note("missing-skeleton-id", "Effect cannot be projected without a skeleton ID", span, relation=relation)
            return
        if relation != "executes" and source not in self.p.nodes:
            self.note("missing-skeleton-id", "Source effect ID is absent from skeleton", span)
            return
        if target not in self.p.nodes:
            self.note("missing-skeleton-id", "Target effect ID is absent from skeleton", span)
            return
        edge = (source, relation, target)
        evidence = {"file": span.file, "line": span.line, "reason": reason}
        self.edges.setdefault(edge, [])
        if evidence not in self.edges[edge]:
            self.edges[edge].append(evidence)

    def execute_method(self, key, args=(), kwargs=None, receiver=None, span=Span()):
        method = self.p.methods[key]
        if method.abstract:
            return self.opaque("abstract or external method " + key, span)
        if len(self.frames) >= self.depth_limit:
            self.note("recursion-budget", "Call depth exhausted; tail effects unknown", span, method=key)
            raise Incomplete()
        caller = self.method
        env = {"self": receiver, "this": receiver, GLOBAL_NAMES: set()}
        supplied = dict(kwargs or {})
        if method.language == "python" and set(supplied) & set(method.annotations.get("positional_only", [])):
            raise Raised("TypeError", "keyword supplied for positional-only parameter")
        for param, value in zip(method.params, args):
            if param.name in supplied:
                raise Raised("TypeError", "duplicate argument")
            supplied[param.name] = value
        if len(args) > len(method.params):
            raise Raised("TypeError", "too many arguments")
        if method.language == "python" and any(p.name in method.annotations.get("keyword_only", []) for p in method.params[:len(args)]):
            raise Raised("TypeError", "positional argument supplied for keyword-only parameter")
        self.frames.append((method, env))
        checkpoint = deepcopy(self.state.store) if method.transaction else None
        try:
            for param in method.params:
                if param.name in supplied:
                    env[param.name] = supplied.pop(param.name)
                elif param.dependency:
                    self.note("dependency-marker", "A source call did not ask the framework to resolve Depends", method.span)
                    env[param.name] = Unknown("unresolved dependency marker", param.typ)
                elif param.default is not None:
                    default_key = method.key + ":default:" + param.name
                    if method.language == "python":
                        if default_key not in self.state.globals:
                            self.state.globals[default_key] = self.value(param.default, env)
                        env[param.name] = self.state.globals[default_key]
                    else:
                        env[param.name] = self.value(param.default, env)
                else:
                    if method.language == "python":
                        raise Raised("TypeError", "missing required argument " + param.name)
                    env[param.name] = Unknown("missing method argument", param.typ, param.name)
                value = env[param.name]
                raw = param.typ.split(".")[-1]
                sort = "bool" if raw in {"bool", "boolean"} else "int" if method.language == "python" and raw == "int" else "bv32" if method.language == "java" and raw == "int" else "bv64" if method.language == "java" and raw == "long" else ""
                if isinstance(value, Unknown) and sort:
                    self.note("symbolic-input", "Typed unknown input is constrained symbolically", method.span, parameter=param.name, reason=value.reason)
                    env[param.name] = self.state.symbol(param.typ, sort)
            if supplied:
                raise Raised("TypeError", "unexpected keyword arguments")
            if caller:
                self.add(caller.skeleton_id, "calls", method.skeleton_id, span)
            self.add("scenario:" + self.scenario_id, "executes", method.skeleton_id, method.span)
            completion = self.block(self.p.lower(key), env)
            return completion.value if completion.kind in {"return", "yield"} else None
        except Raised:
            if checkpoint is not None:
                self.state.store = checkpoint
                self.events.append({"kind": "rollback", "method": key, "attempted_edges_preserved": True})
            raise
        finally:
            self.frames.pop()

    def dependency(self, key, typ="", span=Span()):
        if key in self.dependency_cache:
            return self.dependency_cache[key]
        resolved = key if key in self.p.methods else self.p.resolve_function(key, span.file)
        if not resolved:
            return self.opaque("unresolved dependency " + key, span)
        if key in self.resolving_dependencies:
            self.unsupported("cyclic framework dependency", span)
        self.resolving_dependencies.add(key)
        try:
            values = {p.name: self.dependency(p.dependency, p.typ, self.p.methods[resolved].span)
                      for p in self.p.methods[resolved].params if p.dependency}
            value = self.execute_method(resolved, kwargs=values, span=span)
        finally:
            self.resolving_dependencies.remove(key)
        self.dependency_cache[key] = value
        return value

    def source_call(self, key, args=(), kwargs=None, receiver=None, span=Span()):
        if self.p.methods[key].annotations.get("generator"):
            return self.state.new("python.Generator", {"method": key})
        if self.p.methods[key].annotations.get("async"):
            return Awaitable(key, tuple(args), dict(kwargs or {}), receiver, span)
        return self.execute_method(key, args, kwargs, receiver, span)

    def opaque(self, reason, span=Span()):
        self.note("unknown-call", reason + "; reachable state and exceptional completion are unknown", span)
        self.state.havoc()
        if self.choose(("normal", "throw"), f"{span.file}:{span.line}:opaque") == "throw":
            raise Raised("UnknownException", Unknown(reason))
        return Unknown(reason)

    def unsupported(self, reason, span):
        self.note("unsupported", reason + "; no claim about remaining effects", span)
        self.state.havoc()
        raise Incomplete()

    def create(self, typ, args=(), kwargs=None, span=Span(), bean=False, constructing=None):
        from .models import construct, NOT_HANDLED
        module = self.method.module if self.method else self.p.module(span.file)
        resolved = self.p.resolve_type(typ, module, span.file)
        if not resolved:
            if bean:
                return self.state.new(self.p.imports.get(span.file, {}).get(typ, typ))
            modeled = construct(self, typ, args, kwargs or {}, span)
            if modeled is not NOT_HANDLED:
                return modeled
            return self.opaque("unmodeled constructor " + typ, span)
        if bean:
            resolved = resolved if self.p.types[resolved].repository_entity else self.p.implementation(resolved)
            if not resolved:
                return self.opaque("ambiguous dependency injection for " + typ, span)
        info = self.p.types[resolved]
        if info.annotations.get("custom_metaclass") or self.p.methods_of(resolved, "__new__"):
            return self.opaque("custom Python object construction", span)
        constructing = set() if constructing is None else constructing
        if resolved in constructing:
            return Unknown("cyclic construction", resolved)
        constructing = constructing | {resolved}
        fields = {}
        obj = self.state.new(resolved, fields)
        previous_language = self.initialization_language
        self.initialization_language = info.language
        try:
            for field, (field_type, default) in self.p.type_fields(resolved).items():
                if info.language == "python" and field in (kwargs or {}):
                    fields[field] = kwargs[field]
                elif default is not None:
                    fields[field] = self.value(default, {"this": obj, "self": obj})
                elif info.language == "java":
                    fields[field] = False if field_type == "boolean" else 0 if field_type in {"byte", "short", "int", "long", "float", "double"} else None
                else:
                    if info.annotations.get("model"):
                        fields[field] = Unknown("required model field", field_type, field)
        finally:
            self.initialization_language = previous_language
        if bean:
            for field in info.annotations.get("inject", []):
                if field in self.p.type_fields(resolved):
                    field_type = self.p.type_fields(resolved)[field][0]
                    fields[field] = self.create(field_type, span=info.span, bean=True, constructing=constructing)
        if info.language == "python":
            if info.annotations.get("model"):
                fields.update(kwargs or {})
            obj.provided = set(kwargs or {})
            constructors = self.p.methods_of(resolved, "__init__")
        else:
            constructors = self.p.methods_of(resolved, "<init>", len(args))
        if constructors and not bean:
            if len(constructors) != 1:
                return self.opaque("ambiguous constructor overload " + typ, span)
            self.execute_method(constructors[0].key, args, kwargs, obj, span)
        elif args and info.language == "python":
            self.note("model-positional", "Positional model construction is not supported", span)
            return Unknown("invalid model construction", resolved)
        elif kwargs and info.language == "python" and not info.annotations.get("model"):
            raise Raised("TypeError", "object constructor takes no keyword arguments")
        elif args:
            # Lombok constructors only when their declaration requests generation.
            if "AllArgsConstructor" in info.annotations and len(args) == len(fields):
                fields.update(zip(fields, args))
            else:
                return self.opaque("missing source constructor " + typ, span)
        return obj

    def resolve_name(self, name, env, span, bindings=()):
        if name in env:
            return env[name]
        if bindings and any(value.startswith("local:") for value in bindings):
            # Python decides local scope at compile time, before an assignment
            # executes. Falling back to a same-named imported function is wrong.
            raise Raised("UnboundLocalError", name)
        if len(bindings) > 1:
            self.note("ambiguous-name", "LibCST found several lexical bindings", span, name=name, bindings=bindings)
            return Unknown("ambiguous lexical binding", origin=name)
        method = self.method
        if method and method.language == "java":
            obj = env.get("this")
            if isinstance(obj, Object) and name in obj.fields:
                return obj.fields[name]
            static_key = method.owner + "." + name
            if static_key in self.p.globals:
                return self.field(TypeRef(method.owner), name, span)
        file = span.file or (method.span.file if method else "")
        py_module = self.p.lexical_modules.get(file, "")
        global_key = py_module + "." + name
        if method and name in env.get(GLOBAL_NAMES, set()):
            global_key = method.owner + "." + name
        if global_key in self.state.globals:
            return self.state.globals[global_key]
        if global_key in self.p.globals:
            value = self.value(self.p.globals[global_key], {})
            self.state.globals[global_key] = value
            return value
        imported = bindings[0] if bindings else self.p.imports.get(file, {}).get(name)
        if imported:
            if imported.startswith("builtins."):
                return TypeRef(imported.removeprefix("builtins."))
            if imported in self.p.methods:
                return FunctionRef(imported)
            if imported in self.p.globals:
                if imported not in self.state.globals:
                    self.state.globals[imported] = self.value(self.p.globals[imported], {})
                return self.state.globals[imported]
            return TypeRef(imported)
        function = self.p.resolve_function(name, file, method.module if method else "")
        if function:
            return FunctionRef(function)
        resolved = self.p.resolve_type(name, method.module if method else "", file)
        if resolved:
            return TypeRef(resolved)
        intrinsic = {"len", "str", "int", "float", "bool", "list", "dict", "set", "range", "enumerate", "isinstance",
                     "String", "Integer", "Long", "Boolean", "Double", "Object", "System", "Math"}
        if name in intrinsic or name.endswith(("Exception", "Error")):
            return TypeRef(name)
        self.note("unresolved-name", "Name is not bound by source facts or supplied context", span, name=name)
        return Unknown("unresolved source name", origin=name)

    def field(self, obj, name, span):
        if obj is None:
            raise Raised("NullPointerException" if self.language == "java" else "AttributeError")
        if isinstance(obj, Object):
            if obj.typ + "." + name in self.p.globals:
                return self.field(TypeRef(obj.typ), name, span)
            if obj.typ in self.p.types and self.p.types[obj.typ].language == "python":
                properties = [m for m in self.p.methods_of(obj.typ, name, 0) if m.annotations.get("property")]
                if len(properties) == 1:
                    return self.execute_method(properties[0].key, receiver=obj, span=span)
                if name not in obj.fields:
                    getters = self.p.methods_of(obj.typ, "__getattr__", 1)
                    if len(getters) == 1:
                        return self.execute_method(getters[0].key, (name,), receiver=obj, span=span)
                    raise Raised("AttributeError", name)
            return obj.fields.get(name, Unknown("unknown object field", origin=obj.typ + "." + name))
        if isinstance(obj, dict):
            return obj.get(name, Unknown("absent field", origin=name))
        if isinstance(obj, Response):
            return {"body": obj.body, "status_code": obj.status, "status": obj.status, "headers": obj.headers}.get(name, Unknown("response attribute"))
        if isinstance(obj, TypeRef):
            key = obj.name + "." + name
            if key in self.p.methods:
                return FunctionRef(key)
            if key in self.state.globals:
                return self.state.globals[key]
            if key in self.p.globals:
                result = self.value(self.p.globals[key], {})
                self.state.globals[key] = result
                return result
            from .models import static_field, NOT_HANDLED
            result = static_field(self, obj, name)
            return TypeRef(key) if result is NOT_HANDLED else result
        if isinstance(obj, (list, str)) and name == "length":
            return len(obj)
        return Unknown("field on unknown receiver", origin=name)

    def assign(self, target, value, env, span):
        if target.op == "var":
            if self.language == "java" and target.typ:
                value = integer(value, target.typ)
            if target.value in env.get(GLOBAL_NAMES, set()):
                module = self.p.lexical_modules[self.method.span.file]
                self.state.globals[module + "." + target.value] = value
            elif self.language == "java" and target.value not in env and isinstance(env.get("this"), Object) and target.value in env["this"].fields:
                env["this"].fields[target.value] = value
            else:
                env[target.value] = value
        elif target.op == "field":
            obj = self.value(target.args[0], env)
            if obj is None:
                raise Raised("NullPointerException" if self.language == "java" else "AttributeError")
            if isinstance(obj, Object):
                obj.fields[target.value] = value
            elif isinstance(obj, dict):
                obj[target.value] = value
            else:
                self.unsupported("assignment through an unknown receiver", span)
        elif target.op == "index":
            obj, index = (self.value(v, env) for v in target.args)
            if unknown(obj) or unknown(index):
                self.unsupported("unknown indexed assignment", span)
            try:
                obj[index] = value
            except (IndexError, KeyError, TypeError) as exc:
                raise Raised(type(exc).__name__) from None
        elif target.op == "list":
            if not isinstance(value, (list, tuple)) or len(target.args) != len(value):
                raise Raised("ValueError", "unpacking shape")
            for t, v in zip(target.args, value):
                self.assign(t, v, env, span)
        else:
            self.unsupported("unsupported assignment target " + target.op, span)
        return value

    def value(self, expr, env):
        self.tick(expr.span)
        op, args, span = expr.op, expr.args, expr.span
        if op == "const":
            return integer(expr.value, expr.typ) if self.language == "java" else expr.value
        if op == "var":
            return self.resolve_name(expr.value, env, span, expr.bindings)
        if op == "type":
            return TypeRef(self.p.resolve_type(expr.value, self.method.module if self.method else "", span.file) or expr.value)
        if op == "unknown":
            self.note("unknown-value", expr.value, span)
            return Unknown(expr.value, expr.typ)
        if op == "fresh":
            return self.state.symbol(expr.value)
        if op == "field":
            return self.field(self.value(args[0], env), expr.value, span)
        if op == "list":
            return [self.value(a, env) for a in args]
        if op == "dict":
            return {self.value(k, env): self.value(v, env) for k, v in args}
        if op == "slice":
            return slice(*(self.value(a, env) for a in args))
        if op == "index":
            obj, index = (self.value(a, env) for a in args)
            if unknown(obj) or unknown(index):
                return Unknown("unknown index or collection")
            if obj is None:
                raise Raised("NullPointerException" if self.language == "java" else "TypeError")
            if isinstance(obj, Object) and self.language == "python":
                methods = self.p.methods_of(obj.typ, "__getitem__", 1)
                if len(methods) == 1:
                    return self.source_call(methods[0].key, (index,), receiver=obj, span=span)
            try:
                return obj[index]
            except (IndexError, KeyError, TypeError) as exc:
                raise Raised(type(exc).__name__) from None
        if op == "bin":
            left, right = (self.value(a, env) for a in args)
            if self.language == "java" and not (expr.value == "+" and "String" in {a.typ for a in args}):
                if args[0].typ == "char" and isinstance(left, str) and len(left) == 1:
                    left = ord(left)
                if args[1].typ == "char" and isinstance(right, str) and len(right) == 1:
                    right = ord(right)
            if expr.value in {"/", "//", "%"} and symbolic(right):
                # Z3 totalizes division by zero; language exceptions must be
                # forked explicitly before constructing the arithmetic term.
                if self.condition(binary("==", right, 0, self.language), span):
                    raise Raised("ArithmeticException" if self.language == "java" else "ZeroDivisionError")
            return binary(expr.value, left, right, self.language, expr.typ)
        if op == "compare":
            previous = self.value(args[0], env)
            for index, (operator, arg) in enumerate(zip(expr.value, args[1:])):
                next_value = self.value(arg, env)
                result = binary(operator, previous, next_value, self.language)
                if isinstance(previous, Object) and self.language == "python" and operator in {"==", "!="}:
                    custom = self.p.methods_of(previous.typ, "__eq__", 1)
                    if len(custom) == 1:
                        result = self.execute_method(custom[0].key, (next_value,), receiver=previous, span=span)
                        if operator == "!=":
                            result = not self.condition(result, span)
                if index == len(expr.value) - 1:
                    return result
                if not self.condition(result, span):
                    return False
                previous = next_value
            return True
        if op == "bool":
            result = self.value(args[0], env)
            for argument in args[1:]:
                condition = self.condition(result, span)
                if (expr.value == "and" and not condition) or (expr.value == "or" and condition):
                    return condition if self.language == "java" else result
                result = self.value(argument, env)
            return result
        if op == "unary":
            value = self.value(args[0], env)
            if expr.value in {"!", "not"}:
                return not self.condition(value, span)
            if symbolic(value):
                return binary("-", 0, value, self.language, expr.typ) if expr.value == "-" else value if expr.value == "+" else binary("^", value, -1, self.language, expr.typ)
            if unknown(value):
                return Unknown("unary operand", expr.typ)
            try:
                return integer(-value if expr.value == "-" else +value if expr.value == "+" else ~value, expr.typ or "int") if self.language == "java" else -value if expr.value == "-" else +value if expr.value == "+" else ~value
            except TypeError:
                raise Raised("TypeError") from None
        if op == "choose":
            return self.value(args[1] if self.condition(self.value(args[0], env), span) else args[2], env)
        if op == "assign":
            return self.assign(args[0], self.value(args[1], env), env, span)
        if op == "update":
            old = self.value(args[0], env)
            new = binary("+", old, 1 if expr.value.endswith("++") else -1, self.language, expr.typ or "int")
            self.assign(args[0], new, env, span)
            return new if expr.value.startswith("pre") else old
        if op == "cast":
            value = self.value(args[0], env)
            return integer(value, expr.value)
        if op == "instanceof":
            value = self.value(args[0], env)
            if unknown(value):
                return Unknown("instanceof unknown", "boolean")
            return isinstance(value, Object) and self.matches_type(value.typ, expr.value)
        if op == "format":
            values = [self.value(a, env) for a in args]
            if any(isinstance(v, Unknown) for v in values):
                return Unknown("unknown formatted string", "str")
            if any(isinstance(v, (Symbol, Text)) for v in values):
                return Text(tuple(p for v in values for p in (v.parts if isinstance(v, Text) else (v,) if isinstance(v, Symbol) else (str(v),))))
            return "".join(str(v) for v in values)
        if op == "await":
            value = self.value(args[0], env)
            if isinstance(value, Awaitable):
                if value.library:
                    from .models import call
                    return call(self, value.receiver, value.method, value.args, value.kwargs, value.span)
                return self.execute_method(value.method, value.args, value.kwargs, value.receiver, value.span)
            self.unsupported("await of an unmodeled awaitable", span)
        if op == "new":
            return self.create(expr.value, tuple(self.value(a, env) for a in args), span=span)
        if op == "call":
            receiver_expr, positional, named = args
            receiver = self.value(receiver_expr, env) if receiver_expr is not None else None
            values = tuple(self.value(a, env) for a in positional)
            kwargs = {name: self.value(value, env) for name, value in named}
            return self.call(receiver, expr.value, values, kwargs, span, env, receiver_expr is not None, expr.bindings)
        self.unsupported(str(expr.value or op), span)

    def call(self, receiver, name, args, kwargs, span, env, explicit_receiver=True, bindings=()):
        from .models import call, NOT_HANDLED
        if receiver is None and explicit_receiver:
            raise Raised("NullPointerException" if self.language == "java" else "AttributeError")
        if not explicit_receiver:
            resolved = self.resolve_name(name, env, span, bindings)
            if isinstance(resolved, FunctionRef):
                return self.source_call(resolved.name, args, kwargs, span=span)
            if isinstance(resolved, TypeRef):
                typ = self.p.resolve_type(resolved.name, self.method.module if self.method else "", span.file)
                if typ:
                    return self.create(typ, args, kwargs, span)
            if isinstance(env.get("this"), Object):
                targets = self.p.methods_of(env["this"].typ, name, len(args))
                if len(targets) == 1:
                    return self.source_call(targets[0].key, args, kwargs, env["this"], span)
                if name == "getClass":
                    return TypeRef(env["this"].typ)
            if isinstance(resolved, Unknown):
                return self.opaque("unresolved callable " + name, span)
            receiver, name = None, resolved.name if isinstance(resolved, TypeRef) else name
        if isinstance(receiver, Object) and receiver.typ in self.p.types:
            info = self.p.types[receiver.typ]
            if not info.repository_entity and "FeignClient" not in info.annotations:
                targets = self.p.methods_of(receiver.typ, name, len(args) if self.language == "java" else None)
                if len(targets) == 1:
                    return self.source_call(targets[0].key, args, kwargs, receiver, span)
                if len(targets) > 1:
                    return self.opaque("ambiguous source dispatch " + name, span)
        if isinstance(receiver, TypeRef):
            key = receiver.name + "." + name
            if key in self.p.methods:
                return self.source_call(key, args, kwargs, span=span)
            if key in self.p.types:
                return self.create(key, args, kwargs, span)
            if receiver.name in self.p.types:
                targets = self.p.methods_of(receiver.name, name, len(args) if self.language == "java" else None)
                if len(targets) == 1:
                    return self.source_call(targets[0].key, args, kwargs, span=span)
        if isinstance(receiver, Object) and receiver.typ == "httpx.AsyncClient" and name in {"get", "post", "put", "patch", "delete", "request"}:
            return Awaitable(name, tuple(args), dict(kwargs), receiver, span, True)
        result = call(self, receiver, name, args, kwargs, span)
        return self.opaque("unmodeled call " + name, span) if result is NOT_HANDLED else result

    def matches_type(self, actual, expected):
        names = [v.strip().split(".")[-1] for v in re.split(r"[|,]", expected.strip("() "))]
        short = actual.split(".")[-1].split(":")[-1]
        if "*" in names or short in names:
            return True
        if "UnknownException" == short:
            return self.choose((False, True), "unknown exception catch")
        if actual in self.p.types:
            info = self.p.types[actual]
            if any(self.matches_type(parent, expected) for parent in info.parents if parent != actual):
                return True
        if "Throwable" in names or "BaseException" in names or "Exception" in names:
            return True
        runtime = {"ArithmeticException", "NullPointerException", "IllegalArgumentException", "IndexOutOfBoundsException", "NoSuchElementException", "HttpClientErrorException", "HttpServerErrorException"}
        return "RuntimeException" in names and short in runtime

    def block(self, statements, env):
        for stmt in statements:
            completion = self.statement(stmt, env)
            if completion.kind != "normal":
                return completion
        return Completion()

    def statement(self, stmt, env):
        self.tick(stmt.span)
        op, args, span = stmt.op, stmt.args, stmt.span
        if op == "expr":
            self.value(args[0], env)
        elif op in {"assign", "declare"}:
            value = self.value(args[1], env)
            for target in args[0]:
                if op == "declare" and target.op == "var":
                    if env.get(SCOPES):
                        env[SCOPES][-1].setdefault(target.value, (target.value in env, env.get(target.value)))
                    env[target.value] = Unknown("uninitialized local", target.typ)
                self.assign(target, value, env, span)
        elif op == "scope":
            scope = {}
            env.setdefault(SCOPES, []).append(scope)
            try:
                return self.block(stmt.body, env)
            finally:
                env[SCOPES].pop()
                for name, (existed, value) in scope.items():
                    if existed:
                        env[name] = value
                    else:
                        env.pop(name, None)
        elif op == "global":
            env[GLOBAL_NAMES].update(stmt.value)
        elif op in {"return", "yield"}:
            if op == "yield":
                self.note("dependency-cleanup", "Generator dependency setup is modeled; teardown is not", span)
                self.unknown_teardown = True
            return Completion(op, self.value(args[0], env))
        elif op == "throw":
            value = self.value(args[0], env)
            if value is None:
                if self.language == "python" and self.last_exception:
                    raise self.last_exception
                raise Raised("RuntimeError" if self.language == "python" else "NullPointerException")
            raise Raised(value.typ if isinstance(value, Object) else "UnknownException", value)
        elif op == "if":
            return self.block(stmt.body if self.condition(self.value(args[0], env), span) else stmt.other, env)
        elif op in {"break", "continue"}:
            return Completion(op)
        elif op in {"while", "do"}:
            count = 0
            while (op == "do" and count == 0) or self.condition(self.value(args[0], env), span):
                if count >= self.loop_limit:
                    self.note("loop-budget", "Loop tail effects are unknown", span)
                    raise Incomplete()
                count += 1
                completion = self.block(stmt.body, env)
                if completion.kind == "break":
                    return Completion()
                if completion.kind not in {"normal", "continue"}:
                    return completion
                if stmt.value == "for":
                    self.block(stmt.other, env)
            if stmt.value != "for":
                return self.block(stmt.other, env)
        elif op == "foreach":
            values = self.value(args[1], env)
            if unknown(values):
                self.unsupported("iteration over unknown collection", span)
            if not isinstance(values, (list, tuple, dict, str, range)):
                raise Raised("TypeError")
            for index, value in enumerate(values):
                if index >= self.loop_limit:
                    self.note("loop-budget", "Collection loop tail effects unknown", span)
                    raise Incomplete()
                self.assign(args[0], value, env, span)
                completion = self.block(stmt.body, env)
                if completion.kind == "break":
                    return Completion()
                if completion.kind not in {"normal", "continue"}:
                    return completion
            return self.block(stmt.other, env)
        elif op == "try":
            previous_exception = self.last_exception
            try:
                return self.try_statement(stmt, env)
            finally:
                self.last_exception = previous_exception
        elif op == "with":
            managers = []
            for context, target in args:
                value = self.value(context, env)
                if not isinstance(value, Object) or value.typ not in {"sqlmodel.Session", "sqlalchemy.orm.Session", "httpx.Client", "httpx.AsyncClient"}:
                    self.unsupported("unknown context manager", span)
                if target:
                    self.assign(target, value, env, span)
                managers.append(value)
            completion = None
            try:
                completion = self.block(stmt.body, env)
                return completion
            finally:
                if completion is None or completion.kind != "yield":
                    from .models import call
                    for value in reversed(managers):
                        if value.typ in {"sqlmodel.Session", "sqlalchemy.orm.Session"}:
                            call(self, value, "close", (), {}, span)
        elif op == "switch":
            value, groups = self.value(args[0], env), args[1]
            selected, default = None, None
            for index, (labels, is_default, body, rule) in enumerate(groups):
                if is_default:
                    default = index
                for label in labels:
                    if self.condition(equal(value, self.value(label, env)), span):
                        selected = index
                        break
                if selected is not None:
                    break
            selected = selected if selected is not None else default
            if selected is not None:
                for labels, is_default, body, rule in groups[selected:]:
                    completion = self.block(body, env)
                    if completion.kind == "break":
                        return Completion()
                    if completion.kind != "normal":
                        return completion
                    if rule:
                        break
        else:
            self.unsupported(str(stmt.value or op), span)
        return Completion()

    def try_statement(self, stmt, env):
        args = stmt.args
        completion, raised = Completion(), None
        try:
            completion = self.block(stmt.body, env)
            if completion.kind == "normal":
                completion = self.block(stmt.other, env)
        except Raised as exc:
            handled = False
            self.last_exception = exc
            for expected, pname, body in args[0]:
                if self.matches_type(exc.typ, expected):
                    if pname:
                        env[pname] = exc.value if exc.value is not None else self.state.new(exc.typ)
                    try:
                        completion = self.block(body, env)
                    except Raised as new_exc:
                        raised = new_exc
                    handled = True
                    break
            if not handled:
                raised = exc
        final = self.block(args[1], env)
        if final.kind != "normal":
            return final
        if raised:
            raise raised
        return completion

    def request(self, request, caller=None, span=Span()):
        from .protocol import dispatch
        return dispatch(self, request, caller, span)

"""Small technology models shared across adapters. Unknown libraries stay opaque."""
import re
from contextlib import contextmanager
from copy import deepcopy
from urllib.parse import urljoin
from .java import annotation_value, paths

from .values import (Object, Predicate, Query, Raised, Response, Symbol,
                     Text, TypeRef, Unknown, binary, equal, unknown, wire)


NOT_HANDLED = object()
STATUSES = {"OK": 200, "CREATED": 201, "ACCEPTED": 202, "NO_CONTENT": 204,
            "BAD_REQUEST": 400, "UNAUTHORIZED": 401, "FORBIDDEN": 403, "NOT_FOUND": 404,
            "METHOD_NOT_ALLOWED": 405, "CONFLICT": 409, "UNPROCESSABLE_ENTITY": 422,
            "INTERNAL_SERVER_ERROR": 500, "SERVICE_UNAVAILABLE": 503}


def simple(typ):
    return re.sub(r"<.*>", "", typ).split(".")[-1]


def static_field(engine, receiver, name):
    typ = simple(receiver.name)
    if typ == "HttpStatus" and name in STATUSES:
        return STATUSES[name]
    if typ in {"Integer", "Long"} and name in {"MAX_VALUE", "MIN_VALUE"}:
        bits = 31 if typ == "Integer" else 63
        return 2**bits - 1 if name == "MAX_VALUE" else -(2**bits)
    if typ == "HttpMethod" and name in {"GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"}:
        return name
    if typ == "status" and name.startswith("HTTP_"):
        match = re.match(r"HTTP_(\d+)_", name)
        if match:
            return int(match[1])
    return NOT_HANDLED


def construct(engine, typ, args, kwargs, span):
    short = simple(typ)
    if short in {"ResponseEntity", "HttpEntity"}:
        status = args[-1] if args and type(args[-1]) is int and short == "ResponseEntity" else 200
        body = args[0] if args and not (len(args) == 1 and type(args[0]) is int) else None
        return Response(body, status, args[-2] if len(args) > 2 and isinstance(args[-2], dict) else {})
    if typ in {"fastapi.HTTPException", "starlette.exceptions.HTTPException", "HTTPException"}:
        fields = dict(kwargs)
        if args:
            fields["status_code"] = args[0]
        return engine.state.new("HTTPException", fields)
    if short.endswith(("Exception", "Error")):
        return engine.state.new(short, {"message": args[0] if args else None, **kwargs})
    if short in {"ArrayList", "LinkedList", "HashSet", "LinkedHashSet", "List"}:
        if args and unknown(args[0]):
            return Unknown("unknown collection constructor input")
        return list(args[0]) if args and isinstance(args[0], (tuple, list)) else []
    if short in {"HashMap", "LinkedHashMap", "Map", "HttpHeaders"}:
        return dict(args[0]) if args and isinstance(args[0], dict) else {}
    if short == "Session":
        binding = args[0] if args else kwargs.get("bind")
        status = "unbound" if binding is None else "bound" if isinstance(binding, Object) and binding.typ == "sqlalchemy.Engine" else "unknown"
        return engine.state.new("sqlmodel.Session", {**kwargs, "bind": binding, "binding_status": status})
    aliases = {"RestTemplate": "spring.RestTemplate", "JdbcTemplate": "spring.JdbcTemplate", "NamedParameterJdbcTemplate": "spring.NamedParameterJdbcTemplate", "BindingResult": "spring.BindingResult"}
    if short in aliases:
        return engine.state.new(aliases[short], kwargs)
    if short in {"Date"}:
        return engine.state.symbol("Date")
    if short in {"BigDecimal"}:
        if args and type(args[0]) in {int, float}:
            return args[0]
        return Unknown("unsupported decimal construction", "BigDecimal")
    if typ in {"sqlmodel.Session", "sqlalchemy.orm.Session", "httpx.Client", "httpx.AsyncClient"}:
        return engine.state.new(typ, kwargs)
    if short in {"FastAPI", "APIRouter"}:
        return engine.state.new("fastapi." + short, kwargs)
    return NOT_HANDLED


def entity_info(engine, key, span):
    name = key.name if isinstance(key, TypeRef) else key
    resolved = engine.p.resolve_type(name, engine.method.module if engine.method else "", span.file)
    return engine.p.types.get(resolved)


def data_edge(engine, info, span, operation, source_id=None):
    if not info or not info.table:
        engine.note("unmapped-data", "Entity is not mapped to a skeleton table", span, operation=operation)
        return False
    engine.add(source_id or (engine.method.skeleton_id if engine.method else ""), "data", info.table, span, "source " + operation + " on declared entity/table")
    return True


def rows(engine, info, span):
    if not info or not info.table:
        return Unknown("unmapped entity table")
    raw = engine.state.store.read(info.table)
    if isinstance(raw, Unknown):
        return raw
    result = []
    for record in raw:
        fields = {field: record.get(info.columns.get(field, field), Unknown("column absent from supplied row", origin=field))
                  for field in engine.p.type_fields(info.key)}
        fields.update({k: v for k, v in record.items() if k not in info.columns.values() and k not in fields})
        result.append(engine.state.new(info.key, fields))
    return result


def save(engine, obj, info, span, delete=False, source_id=None):
    if not isinstance(obj, Object) or not info or not data_edge(engine, info, span, "delete" if delete else "save", source_id):
        return Unknown("unresolved entity write")
    initial = engine.state.store.read(info.table)
    if isinstance(initial, Unknown):
        return initial
    if info.generated_key and (obj.fields.get(info.primary_key) is None or isinstance(obj.fields.get(info.primary_key), Unknown)):
        obj.fields[info.primary_key] = engine.state.symbol(engine.p.type_fields(info.key).get(info.primary_key, ("id", None))[0])
    key = obj.fields.get(info.primary_key, Unknown("no entity key"))
    column = info.columns.get(info.primary_key, info.primary_key)
    new_rows, updated = [], False
    for record in initial:
        match = equal(record.get(column), key)
        if unknown(match):
            engine.note("unknown-write-key", "Write identity is uncertain; table state is invalidated", span)
            engine.state.store.tainted.add(info.table)
            return obj
        if match:
            updated = True
            if not delete:
                new_rows.append({info.columns.get(k, k): wire(v) for k, v in obj.fields.items()})
        else:
            new_rows.append(record)
    if not updated and not delete:
        new_rows.append({info.columns.get(k, k): wire(v) for k, v in obj.fields.items()})
    engine.state.store.replace(info.table, new_rows)
    return obj


@contextmanager
def session_scope(engine, session):
    status = session.fields.get("binding_status", "provided-bound-input")
    if status == "unbound":
        raise Raised("UnboundExecutionError")
    if status == "unknown":
        engine.note("session-binding-unknown", "Session engine binding is unresolved", engine.method.span)
        if not engine.choose((False, True), "session has an engine binding"):
            raise Raised("UnboundExecutionError")
    outer = engine.state.store
    engine.state.store = engine.state.transactions.setdefault(session.identity, deepcopy(outer))
    try:
        yield
    finally:
        engine.state.transactions[session.identity] = engine.state.store
        engine.state.store = outer


def flush_session(engine, session):
    for obj, delete, source_id, span in engine.state.pending.get(session.identity, []):
        save(engine, obj, engine.p.types.get(obj.typ), span, delete, source_id)
    engine.state.pending[session.identity] = []


def select(engine, query, span):
    info = entity_info(engine, query.entity, span)
    if not data_edge(engine, info, span, "select"):
        return Unknown("unmapped query")
    result = rows(engine, info, span)
    if isinstance(result, Unknown):
        return result
    selected = []
    for obj in result:
        include = True
        for predicate in query.predicates:
            if not isinstance(predicate, Predicate):
                engine.note("unknown-query", "Unsupported query predicate", span)
                return Unknown("unsupported query predicate")
            field = predicate.field.split(".")[-1]
            value = binary(predicate.op, obj.fields.get(field, Unknown("query field missing")), predicate.value, "python")
            if not engine.condition(value, span):
                include = False
                break
        if include:
            selected.append(obj)
    if not isinstance(query.offset, int) or (query.limit is not None and not isinstance(query.limit, int)):
        return Unknown("unknown pagination")
    selected = selected[query.offset:None if query.limit is None else query.offset + query.limit]
    if query.delete:
        for obj in selected:
            save(engine, obj, info, span, delete=True)
    return len(selected) if query.count else selected


def repository(engine, receiver, name, args, span):
    if not isinstance(receiver, Object) or receiver.typ not in engine.p.types:
        return NOT_HANDLED
    info = engine.p.types[receiver.typ]
    if not info.repository_entity:
        return NOT_HANDLED
    entity = entity_info(engine, info.repository_entity, span)
    if not entity:
        return Unknown("repository entity is unresolved")
    declarations = engine.p.methods_of(info.key, name, len(args))
    if len(declarations) == 1 and set(declarations[0].annotations) & {"Query", "NativeQuery"}:
        declaration = declarations[0]
        raw = declaration.annotations.get("NativeQuery", declaration.annotations.get("Query", ""))
        if "NativeQuery" not in declaration.annotations and not re.search(r"\bnativeQuery\s*=\s*true\b", raw):
            engine.note("jpql-unmodeled", "JPQL is not treated as native SQL or as a derived method query", span)
            return Unknown("JPQL semantics are outside this model")
        # A concatenated/computed annotation is not its first string literal.
        outside_strings = re.sub(r'"(?:\\.|[^"\\])*"', '""', raw)
        if "+" in outside_strings:
            engine.note("sql-query-unknown", "Computed native SQL annotation is not a single literal", span)
            return Unknown("computed SQL annotation")
        from .sql_queries import evaluate
        selected = evaluate(engine, annotation_value(raw, "value") or annotation_value(raw), {p.alias or p.name: value for p, value in zip(declaration.params, args)}, span)
        if isinstance(selected, Unknown):
            return selected
        returned = declaration.return_type
        if simple(returned) in {"long", "Long", "int", "Integer", "String"}:
            return next(iter(selected[0].values())) if selected else None
        values = [engine.state.new(entity.key, {field: row.get(entity.columns.get(field, field), Unknown("SQL projection omits entity field", origin=field)) for field in engine.p.type_fields(entity.key)}) for row in selected]
        if "Optional" in returned:
            return engine.state.new("java.util.Optional", {"value": values[0] if values else None})
        return values if any(part in returned for part in ["List<", "Set<", "Collection<", "Iterable<"]) else values[0] if values else None
    if name in {"save", "saveAndFlush", "insert"}:
        return save(engine, args[0] if args else None, entity, span)
    if name in {"delete", "deleteById"}:
        obj = args[0] if args and isinstance(args[0], Object) else engine.state.new(entity.key, {entity.primary_key: args[0] if args else Unknown("missing key")})
        save(engine, obj, entity, span, delete=True)
        return None
    predicates = []
    if name in {"findById", "getById", "existsById"}:
        predicates = [Predicate(entity.primary_key, "==", args[0] if args else Unknown("missing key"))]
    elif name.startswith(("findBy", "findAllBy", "existsBy", "countBy")):
        suffix = re.sub(r"^(?:findAllBy|findBy|existsBy|countBy)", "", name)
        parts = re.split("And", suffix)
        if len(parts) != len(args) or any(re.search(r"(?:Or|LessThan|GreaterThan|Containing|OrderBy)", p) for p in parts):
            return NOT_HANDLED
        predicates = [Predicate(field[0].lower() + field[1:], "==", arg) for field, arg in zip(parts, args)]
    elif name not in {"findAll", "count"}:
        return NOT_HANDLED
    selected = select(engine, Query(entity.key, predicates), span)
    if isinstance(selected, Unknown):
        return selected
    if name.startswith("exists"):
        return bool(selected)
    if name.startswith("count"):
        return len(selected)
    if name in {"findById", "getById"}:
        result = selected[0] if selected else None
        declarations = engine.p.methods_of(info.key, name, len(args))
        returns_optional = any("Optional" in m.return_type for m in declarations)
        if not declarations and any("JpaRepository" in p or "CrudRepository" in p for p in info.parents):
            returns_optional = name == "findById"
        return engine.state.new("java.util.Optional", {"value": result}) if returns_optional else result
    declarations = engine.p.methods_of(info.key, name, len(args))
    scalar_return = len(declarations) == 1 and declarations[0].return_type.split(".")[-1] == entity.name
    return selected[0] if selected and scalar_return else None if scalar_return else selected


def http(engine, receiver, name, args, kwargs, span):
    typ = receiver.typ if isinstance(receiver, Object) else receiver.name if isinstance(receiver, TypeRef) else ""
    is_java = typ in {"spring.RestTemplate", "org.springframework.web.client.RestTemplate", "RestTemplate"}
    is_python = typ in {"requests", "httpx", "httpx.Client", "httpx.AsyncClient"}
    if not is_java and not is_python:
        return NOT_HANDLED
    method, body, url = "GET", {}, None
    if is_java:
        if name in {"getForObject", "getForEntity"}:
            url = args[0] if args else None
        elif name in {"postForObject", "postForEntity"}:
            method, url, body = "POST", args[0] if args else None, args[1] if len(args) > 1 else {}
        elif name in {"put", "delete"}:
            method, url = name.upper(), args[0] if args else None
            body = args[1] if name == "put" and len(args) > 1 else {}
        elif name == "exchange":
            url, method = args[:2] if len(args) >= 2 else (None, Unknown("missing HTTP verb"))
            body = args[2] if len(args) > 2 else {}
        else:
            return NOT_HANDLED
        if isinstance(body, Response):
            body = body.body
    elif name in {"get", "post", "put", "patch", "delete", "head", "options", "request"}:
        if name == "request":
            method = args[0] if args else kwargs.get("method", "GET")
            url = args[1] if len(args) > 1 else kwargs.get("url")
        else:
            method, url = name.upper(), args[0] if args else kwargs.get("url")
        body = kwargs.get("json", kwargs.get("data", {}))
    else:
        return NOT_HANDLED
    if isinstance(receiver, Object) and "base_url" in receiver.fields and isinstance(url, str):
        base = receiver.fields["base_url"]
        url = urljoin(base, url) if isinstance(base, str) else Unknown("unknown HTTP client base URL")
    response = engine.request({"method": method, "url": url, "body": wire(body), "query": kwargs.get("params", {}), "headers": kwargs.get("headers", {})}, engine.method, span)
    if is_java:
        status = response.status
        if type(status) is int and status >= 400:
            raise Raised("HttpClientErrorException" if status < 500 else "HttpServerErrorException", response)
        if unknown(status) and engine.choose((False, True), "RestTemplate unknown error status"):
            raise Raised("HttpClientErrorException", response)
        return response.body if name.endswith("ForObject") else response
    return response


def call(engine, receiver, name, args, kwargs, span):
    if isinstance(receiver, Object) and receiver.typ in {"spring.JdbcTemplate", "spring.NamedParameterJdbcTemplate"} and name in {"queryForList", "queryForObject", "queryForMap"}:
        from .sql_queries import evaluate
        parameters = args[1] if len(args) > 1 and isinstance(args[1], (dict, list, tuple)) else args[2:] if name == "queryForObject" else args[1:]
        selected = evaluate(engine, args[0] if args else None, parameters, span)
        if isinstance(selected, Unknown) or name == "queryForList":
            return selected
        if not selected:
            raise Raised("EmptyResultDataAccessException")
        if len(selected) != 1:
            raise Raised("IncorrectResultSizeDataAccessException")
        return next(iter(selected[0].values())) if name == "queryForObject" else selected[0]
    if isinstance(receiver, Object) and receiver.typ in engine.p.types:
        info = engine.p.types[receiver.typ]
        if "FeignClient" in info.annotations:
            declarations = engine.p.methods_of(info.key, name, len(args))
            if len(declarations) == 1:
                method = declarations[0]
                mapping = next(((k, v) for k, v in method.annotations.items() if k.endswith("Mapping")), None)
                if mapping:
                    attribute, raw = mapping
                    route = paths(raw)
                    verbs = re.findall(r"RequestMethod\.(\w+)", raw) if attribute == "RequestMapping" else [attribute.removesuffix("Mapping").upper()]
                    service = annotation_value(info.annotations["FeignClient"], "name") or annotation_value(info.annotations["FeignClient"], "value") or annotation_value(info.annotations["FeignClient"])
                    if len(route) == 1 and len(verbs) == 1 and service:
                        path, body = route[0], {}
                        for param, value in zip(method.params, args):
                            if param.location == "path":
                                if isinstance(value, str):
                                    path = path.replace("{" + (param.alias or param.name) + "}", value)
                                else:
                                    return engine.opaque("nonliteral Feign path variable", span)
                            else:
                                body = wire(value)
                        response = engine.request({"method": verbs[0], "url": "http://" + service + path, "body": body}, engine.method, span)
                        if type(response.status) is int and response.status >= 400:
                            raise Raised("FeignException", response)
                        if "fallback" in info.annotations["FeignClient"]:
                            engine.note("feign-fallback", "Feign fallback/circuit breaker behavior is outside the model", span)
                        return response.body
    result = repository(engine, receiver, name, args, span)
    if result is not NOT_HANDLED:
        return result
    result = http(engine, receiver, name, args, kwargs, span)
    if result is not NOT_HANDLED:
        return result
    if isinstance(receiver, Response):
        if name in {"getBody", "json"}:
            return receiver.body
        if name in {"getStatusCodeValue", "getStatusCode"}:
            return receiver.status
        if name == "raise_for_status":
            if unknown(receiver.status):
                if engine.choose((False, True), "unknown HTTP status"):
                    raise Raised("HTTPStatusError", receiver)
            elif receiver.status >= 400:
                raise Raised("HTTPStatusError", receiver)
            return None
    if isinstance(receiver, Query):
        if name in {"where", "filter"}:
            receiver.predicates.extend(args)
            return receiver
        if name in {"offset", "limit"}:
            setattr(receiver, name, args[0] if args else Unknown("pagination"))
            return receiver
    if isinstance(receiver, Object):
        if receiver.typ in {"sqlmodel.Session", "sqlalchemy.orm.Session"}:
            if name == "get" and len(args) >= 2:
                info = entity_info(engine, args[0], span)
                query = Query(info.key, [Predicate(info.primary_key, "==", args[1])]) if info else None
                with session_scope(engine, receiver):
                    if receiver.fields.get("autoflush", True):
                        flush_session(engine, receiver)
                    selected = select(engine, query, span) if query else Unknown("unknown session entity")
                return selected[0] if isinstance(selected, list) and selected else None if selected == [] else selected
            if name in {"add", "delete"}:
                if args and isinstance(args[0], Object):
                    engine.state.pending.setdefault(receiver.identity, []).append((args[0], name == "delete", engine.method.skeleton_id, span))
                    return None
                return Unknown("unknown session entity write")
            if name in {"exec", "execute"} and args and isinstance(args[0], Query):
                with session_scope(engine, receiver):
                    if receiver.fields.get("autoflush", True):
                        flush_session(engine, receiver)
                    selected = select(engine, args[0], span)
                return engine.state.new("sql.Result", {"value": selected})
            if name in {"exec", "execute"} and args and isinstance(args[0], Object) and args[0].typ == "sqlalchemy.TextClause":
                from .sql_queries import evaluate
                with session_scope(engine, receiver):
                    # Textual statements do not trigger ORM autoflush.
                    result = evaluate(engine, args[0].fields.get("text"), args[1] if len(args) > 1 else kwargs.get("params", {}), span)
                return engine.state.new("sql.Result", {"value": result, "mapping_rows": True})
            if name == "flush":
                if engine.state.pending.get(receiver.identity):
                    with session_scope(engine, receiver):
                        flush_session(engine, receiver)
                return None
            if name == "commit":
                if engine.state.pending.get(receiver.identity):
                    with session_scope(engine, receiver):
                        flush_session(engine, receiver)
                transaction = engine.state.transactions.pop(receiver.identity, None)
                if transaction is not None:
                    for table, records in transaction.changes.items():
                        engine.state.store.replace(table, records)
                    engine.state.store.tainted.update(transaction.tainted)
                engine.state.pending[receiver.identity] = []
                return None
            if name in {"rollback", "close"}:
                engine.state.pending[receiver.identity] = []
                engine.state.transactions.pop(receiver.identity, None)
                return None
            if name == "refresh" and args and isinstance(args[0], Object):
                obj = args[0]
                info = engine.p.types.get(obj.typ)
                if info:
                    with session_scope(engine, receiver):
                        selected = select(engine, Query(info.key, [Predicate(info.primary_key, "==", obj.fields.get(info.primary_key))]), span)
                    if isinstance(selected, list) and selected:
                        obj.fields.update(selected[0].fields)
                return None
        if receiver.typ in {"sql.Result", "sql.MappingResult", "sql.ScalarResult"}:
            value = receiver.fields["value"]
            if name == "mappings":
                return engine.state.new("sql.MappingResult", dict(receiver.fields))
            if name == "scalars":
                selected = [next(iter(row.values())) for row in value] if receiver.fields.get("mapping_rows") and isinstance(value, list) else value
                return engine.state.new("sql.ScalarResult", {"value": selected})
            if name in {"all", "first", "one", "one_or_none", "scalar", "scalar_one", "scalar_one_or_none"}:
                if not isinstance(value, list):
                    return value
                if name in {"one", "scalar_one"} and not value:
                    raise Raised("NoResultFound")
                if name in {"one", "scalar_one", "one_or_none", "scalar_one_or_none"} and len(value) > 1:
                    raise Raised("MultipleResultsFound")
                if receiver.fields.get("mapping_rows"):
                    selected = [next(iter(row.values())) for row in value] if name.startswith("scalar") else [tuple(row.values()) for row in value] if receiver.typ == "sql.Result" else value
                else:
                    selected = value
                return selected if name == "all" else selected[0] if selected else None
        if receiver.typ == "spring.BindingResult" and name == "hasErrors":
            return receiver.fields.get("errors", Unknown("validation result"))
        if receiver.typ == "java.util.Optional":
            value = receiver.fields.get("value")
            if name in {"isPresent", "isEmpty"}:
                return value is not None if name == "isPresent" else value is None
            if name in {"get", "orElseThrow"}:
                if value is None:
                    raise Raised("NoSuchElementException")
                return value
            if name == "orElse":
                return value if value is not None else args[0]
        if receiver.typ in engine.p.types:
            info = engine.p.types[receiver.typ]
            if name in {"model_dump", "dict"} and info.language == "python":
                exclude_unset = kwargs.get("exclude_unset", False)
                return {k: v for k, v in receiver.fields.items() if not exclude_unset or receiver.provided is None or k in receiver.provided}
            if name == "sqlmodel_update" and args and isinstance(args[0], dict):
                receiver.fields.update(args[0])
                return receiver
            if set(info.annotations) & {"Data", "Getter", "Setter"}:
                prefix = "get" if name.startswith("get") else "is" if name.startswith("is") else "set" if name.startswith("set") else ""
                field = name[len(prefix):]
                field = field[:1].lower() + field[1:]
                if prefix and field in receiver.fields:
                    if prefix == "set" and args:
                        receiver.fields[field] = args[0]
                        return None
                    return receiver.fields[field]
    if isinstance(receiver, TypeRef):
        typ = simple(receiver.name)
        qualified = receiver.name + "." + name
        if qualified in {"sqlalchemy.create_engine", "sqlmodel.create_engine"}:
            return engine.state.new("sqlalchemy.Engine", {"url": args[0] if args else Unknown("missing database URL"), **kwargs})
        if qualified in {"sqlalchemy.text", "sqlalchemy.sql.text", "sqlalchemy.sql.expression.text"}:
            return engine.state.new("sqlalchemy.TextClause", {"text": args[0] if args else Unknown("missing SQL text")})
        if qualified in {"httpx.Client", "httpx.AsyncClient", "sqlmodel.Session", "sqlalchemy.orm.Session", "fastapi.HTTPException"}:
            return construct(engine, qualified, args, kwargs, span)
        if receiver.name in engine.p.types:
            info = engine.p.types[receiver.name]
            if name in {"model_validate", "parse_obj"} and args:
                fields = wire(args[0])
                if not isinstance(fields, dict):
                    return Unknown("unknown model input")
                fields.update(kwargs.get("update", {}))
                return engine.create(info.key, kwargs=fields, span=span)
        if typ in {"ResponseEntity"}:
            if name == "ok":
                return Response(args[0] if args else None, 200) if args else engine.state.new("spring.ResponseBuilder", {"status": 200})
            if name in {"status", "notFound", "badRequest", "noContent"}:
                status = args[0] if name == "status" and args else {"notFound": 404, "badRequest": 400, "noContent": 204}.get(name, 200)
                return engine.state.new("spring.ResponseBuilder", {"status": status})
        if typ in {"List", "Arrays", "Collections", "Set"} and name in {"of", "asList", "singletonList", "emptyList", "singleton", "emptySet"}:
            return list(args)
        if typ in {"Map"} and name == "of":
            return dict(zip(args[::2], args[1::2]))
        if typ in {"Objects"} and name in {"equals", "nonNull", "isNull", "requireNonNull"}:
            if name == "equals":
                return equal(args[0], args[1])
            if name == "requireNonNull":
                if args[0] is None:
                    raise Raised("NullPointerException")
                return args[0]
            return args[0] is not None if name == "nonNull" else args[0] is None
        if typ == "Assert" and name in {"hasLength", "notNull", "isNull", "isTrue"}:
            value = args[0] if args else None
            valid = Unknown("unknown assertion condition", "boolean") if unknown(value) else bool(value) if name in {"hasLength", "isTrue"} else value is not None if name == "notNull" else value is None
            if not engine.condition(valid, span):
                raise Raised("IllegalArgumentException")
            return None
        if typ == "LoggerFactory" and name == "getLogger":
            return engine.state.new("org.slf4j.Logger")
        if typ in {"UUID", "uuid"} and name in {"randomUUID", "uuid4"}:
            return engine.state.symbol("UUID")
        if typ == "datetime" and name in {"now", "utcnow", "today"}:
            return engine.state.symbol("datetime")
        if typ in {"Optional"} and name in {"empty", "of", "ofNullable"}:
            return engine.state.new("java.util.Optional", {"value": args[0] if args else None})
        if name in {"valueOf", "parseInt", "parseLong"} and typ in {"Integer", "Long", "String"}:
            if isinstance(args[0], TypeRef):
                return Unknown("unmodeled type/enum conversion", typ)
            if isinstance(args[0], Symbol) and typ == "String":
