class CompatibleExceptions(cst.CSTTransformer):
    def __init__(self):
        self.changed = False

    def leave_ExceptHandler(self, original_node, updated_node):
        typ = updated_node.type
        if isinstance(typ, cst.Tuple) and not typ.lpar:
