"""SQLGlot-backed input adapter. SQL is parsed, never executed.

Only literal CREATE/INSERT snapshots are materialized. An unmodelled mutation
invalidates the affected snapshot instead of silently dropping its rows.
"""
from decimal import Decimal, InvalidOperation
import re

import sqlglot
from sqlglot import exp
from sqlglot.errors import ErrorLevel, SqlglotError
from sqlglot.tokens import TokenType

from .values import Unknown


def statements(source, dialect):
    start = 0
    for token in sqlglot.tokenize(source, read=dialect):
        if token.token_type == TokenType.SEMICOLON:
            yield source[start:token.start]
            start = token.end + 1
    if source[start:].strip():
        yield source[start:]


def parsed_statement(source, dialect):
    tokens = sqlglot.tokenize(source, read=dialect)
    if not tokens:
        # SQLGlot treats MySQL versioned comments as comments. A dump can put
        # executable SQL there. Inspect only lexer-confirmed comment chunks,
        # never regex-rewrite strings containing comment-like text.
        for match in re.finditer(r"/\*!\d*\s*(.*?)\*/", source, re.S):
            yield from parsed_statement(match[1], dialect)
        return
    words = [token.text.upper() for token in tokens]
    if words[0] in {"LOCK TABLES", "UNLOCK TABLES"} or words[:2] in [["LOCK", "TABLES"], ["UNLOCK", "TABLES"]]:
        return
    if len(words) == 5 and words[:2] == ["ALTER", "TABLE"] and words[-2:] in [["DISABLE", "KEYS"], ["ENABLE", "KEYS"]]:
        return
    yield sqlglot.parse_one(source, read=dialect, error_level=ErrorLevel.RAISE)


def literal(node):
    if isinstance(node, exp.Null):
        return None
    if isinstance(node, exp.Boolean):
        return bool(node.this)
    if isinstance(node, exp.Paren):
        return literal(node.this)
    if isinstance(node, exp.Neg):
        value = literal(node.this)
        return -value if isinstance(value, (int, Decimal)) and type(value) is not bool else Unknown("non-numeric SQL negation")
    if isinstance(node, exp.Literal):
        if node.is_string:
            return Unknown("SQL text contains undecodable bytes") if "\ufffd" in node.this else node.this
        try:
            return int(node.this) if node.is_int else Decimal(node.this)
        except (ValueError, InvalidOperation):
            pass
    return Unknown("unsupported SQL expression", origin=node.sql()[:120] if node is not None else "")


def snapshot(source, facts, dialect="mysql"):
    base, schemas, types, warnings, tainted, database = {}, {}, {}, [], set(), ""
    all_tables = {key for key, node in facts.nodes.items() if node.get("kind") == "data_resource"}
    if "\ufffd" in source:
        warnings.append("Context contains non-UTF8 bytes; affected SQL values remain unknown")

    def table_info(node):
        table = node.this if isinstance(node, exp.Schema) else node
        if not isinstance(table, exp.Table):
            return "", "", ""
        schema = table.db or database
        return facts.table_id(table.name, schema), schema, table.name

    def apply(node):
        nonlocal database
        if node is None:
            return
        if isinstance(node, exp.Use):
            database = node.this.name
        elif isinstance(node, exp.Create) and str(node.args.get("kind", "")).upper() == "TABLE":
            rid, schema, table = table_info(node.this)
            columns = [column.name for column in node.this.expressions if isinstance(column, exp.ColumnDef)] if isinstance(node.this, exp.Schema) else []
            schemas[schema, table] = columns
            if rid:
                types[rid] = {column.name: column.kind.sql() for column in node.this.expressions if isinstance(column, exp.ColumnDef)} if isinstance(node.this, exp.Schema) else {}
                base.setdefault(rid, [])
                if not columns or node.expression is not None:
                    tainted.add(rid)
                    warnings.append("CREATE TABLE without a literal column schema: " + rid)
        elif isinstance(node, exp.Insert):
            rid, schema, table = table_info(node.this)
            if not rid:
                warnings.append(f"Unmapped context table: {schema}.{table}")
                return
            columns = [column.name for column in node.this.expressions] if isinstance(node.this, exp.Schema) else schemas.get((schema, table))
            if not columns or not isinstance(node.expression, exp.Values) or node.args.get("conflict"):
                tainted.add(rid)
                warnings.append("INSERT requires known columns and literal VALUES: " + rid)
                return
            for row in node.expression.expressions:
                if not isinstance(row, exp.Tuple) or len(columns) != len(row.expressions):
                    tainted.add(rid)
                    warnings.append("SQL column/value count mismatch: " + rid)
                    continue
                base.setdefault(rid, []).append(dict(zip(columns, map(literal, row.expressions))))
        elif isinstance(node, (exp.Set, exp.Transaction, exp.Commit, exp.Rollback)):
            return
        elif isinstance(node, exp.Create) and str(node.args.get("kind", "")).upper() in {"DATABASE", "SCHEMA", "INDEX"}:
            return
        elif isinstance(node, exp.Drop) and str(node.args.get("kind", "")).upper() == "TABLE":
            rid, _, _ = table_info(node.this)
            if rid:
                base.pop(rid, None)
                tainted.discard(rid)
        elif isinstance(node, exp.Command) and str(node.this).upper() in {"LOCK", "UNLOCK", "DELIMITER"}:
            return
        else:
            tables = list(node.find_all(exp.Table))
            affected = {rid for table in tables if (rid := table_info(table)[0])}
            tainted.update(affected or all_tables)
            warnings.append("Unsupported context SQL statement: " + node.sql()[:120])

    try:
        for statement in statements(source, dialect):
            if not statement.strip():
                continue
            try:
                nodes = list(parsed_statement(statement, dialect))
            except SqlglotError as exc:
                warnings.append("SQLGlot could not parse context statement: " + str(exc)[:160])
                tainted.update(all_tables)
                continue
            for node in nodes:
                apply(node)
    except SqlglotError as exc:
        warnings.append("SQLGlot could not tokenize context: " + str(exc)[:160])
        tainted.update(all_tables)
    return {key: tuple(rows) for key, rows in base.items()}, types, tainted, warnings

"""SQLGlot read-only relational plans over supplied in-memory snapshots.

The upstream optimizer/planner/executor performs selection, joins, ordering
and COUNT. This adapter binds inputs, checks its supported semantic boundary,
projects source effects and supplies tables. No database connection is made.
"""
from math import prod

import sqlglot
from sqlglot import exp
from sqlglot.errors import SqlglotError
from sqlglot.executor import execute
from sqlglot.executor.table import Table
from sqlglot.tokens import TokenType

from .values import Unknown, unknown


# Restrict execution to the tested integer/boolean/string/NULL subset. In
# particular no user-defined functions, filesystem tables or arbitrary code.
SUPPORTED = {"Select", "From", "Table", "TableAlias", "Identifier", "Column", "Star", "Alias",
             "Literal", "Boolean", "Null", "Neg", "Paren", "Where", "And", "Or", "Not", "Is",
             "EQ", "NEQ", "GT", "GTE", "LT", "LTE", "Join", "Order", "Ordered", "Limit", "Offset",
             "Count", "Distinct", "Group", "Having", "Placeholder", "In", "Tuple"}


def evaluate(engine, source, params, span):
    def unresolved(message):
        engine.note("sql-query-unknown", message, span)
        return Unknown(message)

    if not isinstance(source, str):
        return unresolved("SQL text is not statically known")
    dialect = engine.context.get("sql_dialect", "mysql")
    try:
        # Token offsets, rather than a regex, preserve '?' inside SQL strings.
        markers = [token for token in sqlglot.tokenize(source, read=dialect) if token.token_type == TokenType.PLACEHOLDER and token.text == "?"]
        positional = list(params) if isinstance(params, (tuple, list)) else []
        values = dict(params) if isinstance(params, dict) else {}
        for index, token in reversed(list(enumerate(markers))):
            key = "__polygraph_arg_" + str(index)
            source = source[:token.start] + ":" + key + source[token.end + 1:]
            values[key] = positional[index] if index < len(positional) else Unknown("missing positional SQL input")
        node = sqlglot.parse_one(source, read=dialect)
    except SqlglotError as exc:
        return unresolved("SQLGlot parse failed: " + str(exc)[:160])
    if not isinstance(node, exp.Select) or any(type(item).__name__ not in SUPPORTED for item in node.walk()):
        if not isinstance(node, exp.Select):
            engine.state.store.havoc()
        return unresolved("SQL query is outside the tested read-only relational subset")
    for item in list(node.find_all(exp.Placeholder)):
        value = values.get(item.name, Unknown("missing named SQL input", origin=item.name))
        if type(value) not in {str, int, bool, type(None)}:
            return unresolved("SQL input is symbolic or has an unsupported scalar type")
        item.replace(exp.convert(value))
    if any(isinstance(item, exp.Literal) and not item.is_string and not item.is_int for item in node.walk()):
        return unresolved("Non-integer SQL numeric semantics are not verified")
    tables, schema, cardinalities = {}, {}, []
    for table in node.find_all(exp.Table):
        rid = engine.p.table_id(table.name, table.db)
        if not rid:
            return unresolved("SQL table does not map uniquely to the input skeleton: " + table.sql())
        engine.add(engine.method.skeleton_id if engine.method else "", "data", rid, span, "source SQL parsed by SQLGlot")
        rows = engine.state.store.read(rid)
        if isinstance(rows, Unknown):
            return unresolved(rows.reason)
        columns = dict(engine.state.store.schemas.get(rid, {}))
        for row in rows:
            for column, value in row.items():
                if type(value) not in {str, int, bool, type(None)}:
                    return unresolved("SQL snapshot contains unknown or unsupported scalar values")
                inferred = "BOOLEAN" if type(value) is bool else "BIGINT" if type(value) is int else "TEXT" if isinstance(value, str) else "UNKNOWN"
                if columns.get(column, "UNKNOWN") == "UNKNOWN":
                    columns[column] = inferred
        for info in engine.p.types.values():
            if info.table == rid:
                for field, (typ, _) in engine.p.type_fields(info.key).items():
                    columns.setdefault(info.columns.get(field, field), "BIGINT" if typ in {"int", "Integer", "long", "Long"} else "BOOLEAN" if typ in {"bool", "boolean"} else "TEXT")
        if not columns:
            # An empty supplied table still suffices for COUNT(*)/SELECT *.
            # Explicit unknown column references are rejected by the optimizer.
            columns = {"__empty_snapshot": "UNKNOWN"}
        if any(set(columns) - set(row) for row in rows):
            return unresolved("Snapshot omits column values required by its schema")
        name = "snapshot_" + str(len(tables))
        tables[name] = Table(columns, [tuple(row[column] for column in columns) for row in rows])
        schema[name] = columns
        cardinalities.append(len(rows))
        alias = table.alias_or_name
        table.set("this", exp.to_identifier(name))
        table.set("db", None)
        table.set("catalog", None)
        table.set("alias", exp.TableAlias(this=exp.to_identifier(alias)))
    for column in node.find_all(exp.Column):
        column.set("db", None)
        column.set("catalog", None)
    work = prod(cardinalities) if cardinalities else 1
    if work > engine.step_limit - engine.operations:
        engine.unsupported("SQL snapshot row-product exceeds the operation budget", span)
    engine.operations += work
    try:
        result = execute(node, schema=schema, tables=tables, dialect=dialect)
    except (SqlglotError, ValueError, TypeError, KeyError, IndexError, NotImplementedError) as exc:
        return unresolved("SQLGlot relational evaluation failed: " + str(exc)[:160])
    return [dict(zip(result.columns, row)) for row in result.rows]

"""Shared HTTP boundary: route selection, wire values, binding and error status."""
import re
from urllib.parse import parse_qs, unquote, urlsplit

from .ir import Span
from .values import Awaitable, Object, Raised, Response, Symbol, Text, Unknown, unknown, wire


def route_match(path, template):
    pieces, names, start = [], [], 0
    for match in re.finditer(r"\{([^}:]+)(?::([^}]+))?\}", template):
        pieces.append(re.escape(template[start:match.start()]))
        names.append(match[1])
        pieces.append("(" + (".+" if match[2] == "path" else "[^/]+") + ")")
        start = match.end()
    pieces.append(re.escape(template[start:]))
    matched = re.fullmatch("".join(pieces), path)
    return dict(zip(names, (unquote(v) for v in matched.groups()))) if matched else None


def scalar(value, typ, language):
    if unknown(value):
        return value
    raw = typ.strip().split(".")[-1]
    if raw == "UUID":
        if not isinstance(value, str) or not re.fullmatch(r"[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}", value):
            raise Raised("RequestValidationError")
        return value.lower()
    if raw in {"int", "Integer", "long", "Long"}:
        try:
            if isinstance(value, bool):
                return int(value) if language == "python" else Unknown("invalid numeric parameter", typ)
            result = int(value)
            if language == "java" and not (-(2**(31 if raw in {"int", "Integer"} else 63)) <= result < 2**(31 if raw in {"int", "Integer"} else 63)):
                return Unknown("out-of-range HTTP integer", typ)
            return result
        except (ValueError, TypeError):
            raise Raised("RequestValidationError") from None
    if raw in {"bool", "boolean", "Boolean"}:
        if type(value) is bool:
            return value
        if str(value).lower() in {"true", "1", "on", "yes"}:
            return True
        if str(value).lower() in {"false", "0", "off", "no"}:
            return False
        raise Raised("RequestValidationError")
    if raw in {"float", "double", "Float", "Double"}:
        try:
            return float(value)
        except (ValueError, TypeError):
            raise Raised("RequestValidationError") from None
    return value


def bind_body(engine, value, typ, span):
    resolved = engine.p.resolve_type(typ, engine.p.module(span.file), span.file)
    if not resolved or value is None or unknown(value):
        return value
    if not isinstance(value, dict):
        raise Raised("RequestValidationError")
    fields = engine.p.type_fields(resolved)
    kwargs = {}
    for name, (ftype, default) in fields.items():
        if name in value:
            kwargs[name] = scalar(value[name], ftype, engine.p.types[resolved].language)
        elif default is None:
            if engine.p.types[resolved].language == "python":
                raise Raised("RequestValidationError")
            kwargs[name] = Unknown("body field not provided", ftype, name)
    obj = engine.create(resolved, kwargs=kwargs, span=span)
    if isinstance(obj, Object):
        obj.fields.update({k: v for k, v in kwargs.items()})
    return obj


def dispatch(engine, request, caller=None, span=Span()):
    verb = request.get("method", "GET")
    url = request.get("url", request.get("path", ""))
    symbols = {}
    if isinstance(url, Text):
        pieces = []
        for part in url.parts:
            if isinstance(part, Symbol):
                if part.typ.split(".")[-1] not in {"UUID", "int", "Integer", "long", "Long"}:
                    engine.note("symbolic-url-shape", "A symbolic string may change URL structure", span)
                    if not engine.choose((False, True), "symbolic URL remains one path segment"):
                        return Response(Unknown("symbolic URL routing"), Unknown("symbolic URL status"))
                token = "__polygraph_symbol_" + str(len(symbols)) + "__"
                symbols[token] = part
                pieces.append(token)
            elif isinstance(part, str):
                pieces.append(part)
            else:
                return Response(Unknown("unknown HTTP address piece"), Unknown("unknown HTTP status"))
        url = "".join(pieces)
    if not isinstance(url, str) or not isinstance(verb, str):
        engine.note("unknown-request-address", "HTTP method or address is unknown", span)
        return Response(Unknown("unknown HTTP address"), Unknown("unknown HTTP status"))
    address = urlsplit(url)
    path = address.path or "/"
    query = {k: v[-1] if len(v) == 1 else v for k, v in parse_qs(address.query, keep_blank_values=True).items()}
    query.update(request.get("query", {}) if isinstance(request.get("query", {}), dict) else {})
    headers = {str(k).lower(): v for k, v in request.get("headers", {}).items()}
    module = request.get("module", "")
    if not module and address.hostname:
        services = engine.context.get("services", {})
        matches = []
        for key, meta in engine.p.modules.items():
            candidate = meta.get("name", key.removeprefix("module:"))
            hosts = {candidate, *meta.get("deployment_units", [])}
            configured = services.get(candidate)
            if isinstance(configured, str):
                hosts.add(urlsplit(configured).hostname)
            if address.hostname in hosts:
                matches.append(candidate)
        if len(matches) == 1:
            module = matches[0]
        elif address.hostname not in {"localhost", "127.0.0.1"}:
            engine.note("external-host", "HTTP host is not mapped to a source deployment", span, hostname=address.hostname)
            engine.state.store.havoc()
            return Response(Unknown("external service response"), Unknown("external service status"))
    candidates = []
    for endpoint in engine.p.endpoints:
        if module and module != endpoint.module:
            continue
        if endpoint.verb not in {"*", verb.upper()}:
            continue
        parameters = route_match(path, endpoint.path)
        if parameters is not None:
            candidates.append((endpoint, parameters))
    if not candidates:
        engine.note("unresolved-request", "No source-derived handler matches HTTP method/path/module", span, method=verb, url=url, module=module)
        return Response(Unknown("unresolved server response"), Unknown("unresolved server status"))
    # Spring prefers literal paths; Starlette/FastAPI uses registration order.
    spring = all(c[0].framework == "spring" for c in candidates)
    if spring:
        specificity = max(len(re.sub(r"\{[^}]+\}", "", c[0].path)) for c in candidates)
        candidates = [c for c in candidates if len(re.sub(r"\{[^}]+\}", "", c[0].path)) == specificity]
    elif all(c[0].framework == "fastapi" for c in candidates) and len({c[0].module for c in candidates}) == 1:
        candidates = candidates[:1]
    if len(candidates) > 1:
        engine.note("ambiguous-route", "All matching source handlers remain hypotheses", span, candidates=[c[0].method for c in candidates])
        choice = engine.choose(tuple(range(len(candidates))), "HTTP handler ambiguity")
    else:
        choice = 0
    endpoint, path_values = candidates[choice]
    path_values = {k: symbols.get(v, v) for k, v in path_values.items()}
    path_values.update(request.get("path_params", {}))
    method = engine.p.methods[endpoint.method]
    risks = [r for r in engine.p.framework_risks if r["module"] == endpoint.module and r["framework"] == endpoint.framework]
    if risks:
        engine.note("framework-lifecycle", "Handler graph is conditional on an unmodeled framework phase", method.span, risks=risks)
        if not engine.context.get("assumptions", {}).get("framework_entry"):
            engine.state.havoc()
            if not engine.choose((False, True), "unmodeled framework lifecycle permits handler"):
                return Response(Unknown("framework may terminate before handler"), Unknown("framework response status"))
    if endpoint.conditions.get("profile_unknown") or endpoint.conditions.get("mount_unknown"):
        engine.note("route-activation-unknown", "Route activation depends on an unspecified profile/condition", method.span)
        if not engine.choose((False, True), "profile activation"):
            return Response(None, 404)
    if endpoint.conditions.get("mapping_constraints"):
        engine.note("mapping-constraints", "Headers/media type route constraints are not fully modeled", method.span)
        if not engine.choose((False, True), "Spring request mapping constraints"):
            return Response(None, 404)
    if "PreAuthorize" in method.annotations:
        engine.note("authorization-precondition", "Spring authorization is outside the model", method.span)
        if not engine.context.get("assumptions", {}).get("authorization_passed") and not engine.choose((False, True), "authorization decision"):
            return Response(None, 403)
    if caller:
        engine.add(caller.skeleton_id, "remote", method.skeleton_id, span, "source HTTP call with method, path and service")
    values = {}
    body = wire(request.get("body", {}))
    old_dependencies = engine.dependency_cache
    old_teardown = engine.unknown_teardown
    engine.unknown_teardown = False
    outer_frames = engine.frames
    engine.frames = []
    engine.dependency_cache = {}
    try:
        for dependency in endpoint.dependencies:
            engine.dependency(dependency, span=method.span)
        for param in method.params:
            location = param.location
            alias = param.alias or param.name
            if param.dependency:
                values[param.name] = engine.dependency(param.dependency, param.typ, method.span)
                continue
            resolved_type = engine.p.resolve_type(param.typ, method.module, method.span.file)
            if location == "path" or alias in path_values:
                value = path_values.get(alias, Unknown("missing path variable", param.typ, alias))
            elif location == "header":
                value = headers.get(alias.lower(), Unknown("header not supplied", param.typ, alias))
            elif location == "body" or (endpoint.framework == "fastapi" and resolved_type):
                value = bind_body(engine, body, param.typ, method.span)
            elif param.typ.split(".")[-1] in {"HttpHeaders"}:
                value = headers
            elif param.typ.split(".")[-1] == "BindingResult":
                value = engine.state.new("spring.BindingResult", {"errors": Unknown("validation has not been evaluated")})
            elif param.typ.split(".")[-1] == "Principal":
                principal = engine.context.get("principal", {})
                value = engine.state.new("java.security.Principal", {"name": principal.get("name", Unknown("authenticated principal not supplied"))})
            elif alias in query:
                value = query[alias]
            elif param.default is not None:
                value = engine.value(param.default, {})
            else:
                value = Unknown("request input not supplied", param.typ, alias)
            values[param.name] = scalar(value, param.typ, method.language)
        receiver = engine.create(method.owner, span=method.span, bean=True) if method.owner in engine.p.types else None
        result = engine.execute_method(method.key, kwargs=values, receiver=receiver, span=span)
        response = result if isinstance(result, Response) else Response(result, endpoint.status)
        if isinstance(response.body, Awaitable):
            engine.note("unawaited-response", "A returned coroutine is not a serializable HTTP body", method.span)
            return Response(None, 500)
        response.body = wire(response.body)
        engine.events.append({"kind": "http", "method": verb.upper(), "path": path, "handler": method.skeleton_id,
