"""Copy-on-write table snapshots; immutable input rows are shared across paths."""
from copy import deepcopy
import gzip
import json

from .values import Object, Symbol, Unknown


class Store:
    def __init__(self, base=None, changes=None, tainted=None, schemas=None):
        self.base = base if base is not None else {}
        self.changes = changes if changes is not None else {}
        self.tainted = tainted if tainted is not None else set()
        self.schemas = schemas if schemas is not None else {}

    def __deepcopy__(self, memo):
        result = Store(self.base, deepcopy(self.changes, memo), self.tainted.copy(), self.schemas)
        memo[id(self)] = result
        return result

    def read(self, table):
        if table in self.tainted:
            return Unknown("table may have been modified by unsupported code", origin=table)
        if table not in self.changes and table not in self.base:
            return Unknown("initial table contents were not supplied", origin=table)
        return list(deepcopy(self.changes.get(table, self.base.get(table, ()))))

    def replace(self, table, rows):
        self.changes[table] = deepcopy(rows)
        self.tainted.discard(table)

    def havoc(self):
        self.tainted.update(set(self.base) | set(self.changes))

    def snapshot(self):
        return {k: self.read(k) for k in sorted(set(self.base) | set(self.changes))}


class State:
    def __init__(self, store=None):
        self.store = store if store is not None else Store()
        self.globals = {}
        self.objects = {}
        self.sequence = 0
        self.pending = {}
        self.transactions = {}
        self.sessions = set()

    def new(self, typ, fields=None):
        self.sequence += 1
        obj = Object(f"o{self.sequence}", typ, fields if fields is not None else {})
        self.objects[obj.identity] = obj
        return obj

    def symbol(self, typ, sort=""):
        self.sequence += 1
        return Symbol(f"fresh:{self.sequence}", typ, sort=sort)

    def havoc(self):
        self.store.havoc()
        for transaction in self.transactions.values():
            transaction.havoc()
        self.pending.clear()
        for obj in self.objects.values():
            obj.fields = {k: Unknown("unknown call may modify reachable object", origin=obj.identity) for k in obj.fields}


def load_context(path, facts, dialect="mysql"):
    if path is None:
        return Store(), {}, ["No initial data context supplied"]
    if path.is_dir():
        candidates = sorted(p for p in path.iterdir() if p.suffix in {".sql", ".gz", ".json"})
        if len(candidates) != 1:
            raise ValueError("Select one context file explicitly when a directory is ambiguous")
        path = candidates[0]
    raw = path.read_bytes()
    if path.suffix == ".gz":
        raw = gzip.decompress(raw)
    if path.name.endswith(".json"):
        context = json.loads(raw)
        tables = context.get("tables", {})
        base = {}
        for name, rows in tables.items():
            rid = facts.table_id(name)
            if not rid:
                raise ValueError("Context table not mapped uniquely to skeleton: " + name)
            base[rid] = tuple(deepcopy(rows))
        schemas = {}
        for name, columns in context.get("table_schemas", {}).items():
            rid = facts.table_id(name)
            if not rid:
                raise ValueError("Context schema table not mapped uniquely to skeleton: " + name)
            schemas[rid] = columns
        return Store(base, schemas=schemas), context, []
    from .sql import snapshot
    base, schemas, tainted, warnings = snapshot(raw.decode("utf-8", errors="replace"), facts, dialect)
    return Store(base, tainted=tainted, schemas=schemas), {}, warnings

"""The shared IR. It contains no parser nodes and no application-specific rules."""
from dataclasses import dataclass, field
from typing import Any


@dataclass(frozen=True)
class Span:
    file: str = ""
    line: int = 0
    column: int = 0


@dataclass(frozen=True)
class Expr:
    op: str
    args: tuple = ()
    value: Any = None
    span: Span = Span()
    typ: str = ""
    bindings: tuple = ()


@dataclass(frozen=True)
class Stmt:
    op: str
    args: tuple = ()
    body: tuple = ()
    other: tuple = ()
    value: Any = None
    span: Span = Span()


@dataclass
class Parameter:
    name: str
    typ: str = ""
    location: str = ""
    alias: str = ""
    default: Expr | None = None
    dependency: str = ""


@dataclass
class Method:
    key: str
    name: str
    owner: str
    module: str
    language: str
    span: Span
    params: list[Parameter]
    return_type: str = ""
    skeleton_id: str = ""
    body: tuple | None = None
    abstract: bool = False
    transaction: bool = False
    doc: str = ""
    annotations: dict = field(default_factory=dict)


@dataclass
class TypeInfo:
    key: str
    name: str
    module: str
    language: str
    span: Span
    fields: dict = field(default_factory=dict)
    parents: list = field(default_factory=list)
    methods: list = field(default_factory=list)
    table: str = ""
    columns: dict = field(default_factory=dict)
    primary_key: str = "id"
    generated_key: bool = False
    repository_entity: str = ""
    annotations: dict = field(default_factory=dict)


@dataclass
class Endpoint:
    method: str
    verb: str
    path: str
    module: str
    framework: str
    status: int = 200
    dependencies: list = field(default_factory=list)
    conditions: dict = field(default_factory=dict)


def pack(value):
    if isinstance(value, (Expr, Stmt, Span)):
        return {"@": type(value).__name__, **{k: pack(v) for k, v in vars(value).items()}}
    if isinstance(value, tuple):
        return {"@": "tuple", "items": [pack(v) for v in value]}
    if isinstance(value, list):
        return [pack(v) for v in value]
    if isinstance(value, dict):
        return {k: pack(v) for k, v in value.items()}
    return value


def unpack(value):
    if isinstance(value, list):
        return [unpack(v) for v in value]
    if isinstance(value, dict):
        kind = value.get("@")
        if kind == "tuple":
            return tuple(unpack(v) for v in value["items"])
        if kind in {"Expr", "Stmt", "Span"}:
            cls = {"Expr": Expr, "Stmt": Stmt, "Span": Span}[kind]
            return cls(**{k: unpack(v) for k, v in value.items() if k != "@"})
        return {k: unpack(v) for k, v in value.items()}
    return value

