"""Python AST -> shared IR, plus source-derived FastAPI contracts. No imports run."""
import ast
from pathlib import PurePosixPath
from libcst import ParserSyntaxError

from .ir import Endpoint, Expr, Method, Parameter, Span, Stmt, TypeInfo
from .python_names import parse as parse_names


def name(node):
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return name(node.value) + "." + node.attr
    return ""


def literal(node, default=None):
    try:
        return ast.literal_eval(node)
    except (ValueError, TypeError, SyntaxError, MemoryError, RecursionError):
        return default


class PythonAdapter:
    def __init__(self, project):
        self.p = project
        self.trees, self.module_names, self.routers, self.mounts = {}, {}, {}, []
        self.roots, self.routes, self.raw_globals = set(), [], {}
        self.file = ""
        self.bindings = {}
        self.node_files = {}

    def span(self, node):
        return Span(self.file, getattr(node, "lineno", 0), getattr(node, "col_offset", 0) + 1)

    def qualified(self, value, file=None):
        file = file or self.file
        first = value.split(".")[0]
        return self.p.imports.get(file, {}).get(first, self.module_names.get(file, "") + "." + first) + value[len(first):]

    def references(self, node):
        file = self.node_files.get(id(node), self.file)
        return self.bindings.get(file, {}).get((getattr(node, "lineno", 0), getattr(node, "col_offset", 0), type(node).__name__), ())

    def canonical(self, node):
        references = self.references(node)
        return references[0] if len(references) == 1 and not references[0].startswith("local:") else self.qualified(name(node), self.node_files.get(id(node), self.file)) if not references else ""

    def framework(self, node, choices):
        value = self.canonical(node)
        return value.split(".")[-1] if value.startswith(("fastapi.", "typing.", "typing_extensions.", "sqlmodel.", "pydantic.", "pydantic_settings.")) and value.split(".")[-1] in choices else ""

    def index(self):
        for file, source in self.p.sources.items():
            if not file.endswith(".py"):
                continue
            self.file = file
            path = PurePosixPath(file)
            # Recover the import package from __init__.py ancestry, not directory names.
            parts = [path.stem] if path.stem != "__init__" else []
            parent = path.parent
            while str(parent) != "." and (parent / "__init__.py").as_posix() in self.p.sources:
                parts.insert(0, parent.name)
                parent = parent.parent
            module = ".".join(parts) or path.parent.name
            self.module_names[file] = module
            self.p.lexical_modules[file] = module
            try:
                package = module if path.stem == "__init__" else module.rpartition(".")[0]
                normalized, self.bindings[file], changed = parse_names(source, module, package)
                tree = ast.parse(normalized, filename=file)
                if changed:
                    self.p.warn("python-syntax-normalized", "LibCST parenthesized exception tuples in memory for the host AST parser", Span(file))
            except (SyntaxError, ParserSyntaxError, UnicodeDecodeError) as exc:
                self.p.warn("python-parse", str(exc), Span(file, getattr(exc, "lineno", 0) or 0))
                continue
            self.trees[file] = tree
            self.node_files.update((id(node), file) for node in ast.walk(tree))
            aliases = self.p.imports.setdefault(file, {})
            for node in tree.body:
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        aliases[alias.asname or alias.name.split(".")[0]] = alias.name if alias.asname else alias.name.split(".")[0]
                elif isinstance(node, ast.ImportFrom):
                    base = node.module or ""
                    if node.level:
                        prefix = module.split(".") if path.stem == "__init__" else module.split(".")[:-1]
                        prefix = prefix[:len(prefix) - node.level + 1]
                        base = ".".join(prefix + ([base] if base else []))
                    for alias in node.names:
                        if alias.name != "*":
                            aliases[alias.asname or alias.name] = base + "." + alias.name
                elif isinstance(node, (ast.Assign, ast.AnnAssign)):
                    targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                    for target in targets:
                        if isinstance(target, ast.Name) and node.value is not None:
                            key = module + "." + target.id
                            self.raw_globals[key] = (file, node.value)
                            self.p.globals[key] = self.expr(node.value)
                elif isinstance(node, ast.ClassDef):
                    self.index_class(node, module)
                elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    self.index_method(node, module, module)

    def index_class(self, node, module):
        key = module + "." + node.name
        info = TypeInfo(key, node.name, self.p.module(self.file), "python", self.span(node), parents=[name(b) for b in node.bases])
        info.annotations["model"] = any(self.framework(b, {"SQLModel", "BaseModel", "BaseSettings"}) for b in node.bases)
        info.annotations["custom_metaclass"] = any(k.arg == "metaclass" for k in node.keywords)
        self.p.add_type(info)
        is_table = any(k.arg == "table" and literal(k.value) is True for k in node.keywords)
        for field in node.body:
            if isinstance(field, (ast.FunctionDef, ast.AsyncFunctionDef)):
                self.index_method(field, key, module)
            elif isinstance(field, ast.AnnAssign) and isinstance(field.target, ast.Name):
                typ = ast.unparse(field.annotation)
                default = self.expr(field.value) if field.value else None
                if isinstance(field.value, ast.Call) and self.framework(field.value.func, {"Field"}):
                    options = {k.arg: k.value for k in field.value.keywords}
                    if literal(options.get("primary_key")) is True:
                        info.primary_key = field.target.id
                    factory = name(options.get("default_factory"))
                    if factory:
                        info.generated_key = True
                        default = Expr("fresh", value="UUID", span=self.span(field)) if factory.endswith(("uuid4", "uuid1")) else Expr("call", (None, (), ()), factory, self.span(field))
                    elif "default" in options:
                        default = self.expr(options["default"])
                    else:
                        default = None
                elif isinstance(field.value, ast.Call) and self.framework(field.value.func, {"Relationship"}):
                    default = Expr("const", value=[] if typ.startswith(("list[", "List[")) else None, span=self.span(field))
                info.fields[field.target.id] = (typ, default)
            elif isinstance(field, ast.Assign):
                for target in field.targets:
                    if isinstance(target, ast.Name) and target.id == "__tablename__":
                        info.table = self.p.table_id(literal(field.value, ""))
        if is_table and not info.table:
            info.table = self.p.table_id(node.name.lower())
        info.annotations["table"] = is_table

    def annotation_parts(self, annotation):
        default_dep = ""
        raw = annotation
        if isinstance(raw, ast.Name):
            global_name = self.qualified(raw.id)
            if global_name in self.raw_globals:
                file, raw = self.raw_globals[global_name]
        if isinstance(raw, ast.Subscript) and self.framework(raw.value, {"Annotated"}):
            elements = raw.slice.elts if isinstance(raw.slice, ast.Tuple) else [raw.slice]
            for item in elements[1:]:
                if isinstance(item, ast.Call) and self.framework(item.func, {"Depends", "Security"}) and item.args:
                    default_dep = self.canonical(item.args[0])
            raw = elements[0]
        return (ast.unparse(raw) if raw else ""), default_dep

    def index_method(self, node, owner, module):
        key = owner + "." + node.name
        params, defaults = [], {}
        positional = node.args.posonlyargs + node.args.args
        for arg, default in zip(positional[-len(node.args.defaults):] if node.args.defaults else [], node.args.defaults):
            defaults[arg.arg] = default
        defaults.update({arg.arg: default for arg, default in zip(node.args.kwonlyargs, node.args.kw_defaults) if default is not None})
        for arg in positional + node.args.kwonlyargs:
            if arg.arg in {"self", "cls"} and owner in self.p.types:
                continue
            typ, dep = self.annotation_parts(arg.annotation)
            default = defaults.get(arg.arg)
            location, alias = "", arg.arg
            if isinstance(default, ast.Call):
                short = self.framework(default.func, {"Depends", "Security", "Query", "Path", "Header", "Body", "Cookie"})
                if short in {"Depends", "Security"} and default.args:
                    dep = self.canonical(default.args[0])
                    default = None
                elif short in {"Query", "Path", "Header", "Body", "Cookie"}:
                    location = short.lower()
                    options = {k.arg: k.value for k in default.keywords}
                    alias = literal(options.get("alias"), arg.arg)
                    default = default.args[0] if default.args and literal(default.args[0], ...) is not ... else options.get("default")
            params.append(Parameter(arg.arg, typ, location, alias, self.expr(default) if default else None, dep))
        annotations = {"async": isinstance(node, ast.AsyncFunctionDef)}
        annotations["generator"] = any(isinstance(n, (ast.Yield, ast.YieldFrom)) for n in ast.walk(node))
        annotations["property"] = any(name(d) == "property" for d in node.decorator_list)
        annotations["keyword_only"] = [a.arg for a in node.args.kwonlyargs]
        annotations["positional_only"] = [a.arg for a in node.args.posonlyargs]
        if any(isinstance(d, ast.Call) and isinstance(d.func, ast.Attribute) and d.func.attr == "middleware" for d in node.decorator_list):
            annotations["middleware"] = True
        if node.args.vararg or node.args.kwarg:
            annotations["variadic"] = True
        method = Method(key, node.name, owner, self.p.module(self.file), "python", self.span(node), params,
                        ast.unparse(node.returns) if node.returns else "", doc=ast.get_docstring(node) or "", annotations=annotations)
        self.p.add_method(method, (node, min([node.lineno] + [d.lineno for d in node.decorator_list]), node.end_lineno))
        if owner in self.p.types:
            self.p.types[owner].methods.append(key)
        for decorator in node.decorator_list:
            if isinstance(decorator, ast.Call) and isinstance(decorator.func, ast.Attribute) and decorator.func.attr in {"get", "post", "put", "patch", "delete", "head", "options", "api_route"}:
                route = literal(decorator.args[0], None) if decorator.args else None
                if not isinstance(route, str):
                    self.p.warn("dynamic-route", "FastAPI route path is not a literal", self.span(decorator))
                    continue
                options = {k.arg: k.value for k in decorator.keywords}
                verbs = literal(options.get("methods"), [decorator.func.attr.upper()])
                deps = self.dependencies(options.get("dependencies"))
                self.routes.append((self.qualified(name(decorator.func.value)), method.key, route, verbs, literal(options.get("status_code"), 200), deps))

    def dependencies(self, node):
        return [self.canonical(item.args[0]) for item in (node.elts if isinstance(node, (ast.List, ast.Tuple)) else [])
                if isinstance(item, ast.Call) and item.args and self.framework(item.func, {"Depends", "Security"})]

    def constant(self, node, file=None, seen=None):
        file = file or self.file
        seen = set() if seen is None else seen
        value = literal(node, ...)
        if value is not ...:
            return value
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            a, b = self.constant(node.left, file, seen), self.constant(node.right, file, seen)
            return a + b if isinstance(a, str) and isinstance(b, str) else None
        key = self.qualified(name(node), file)
        if key in seen:
            return None
        seen.add(key)
        if key in self.raw_globals:
            source, value = self.raw_globals[key]
            return self.constant(value, source, seen)
        # Pydantic settings fields are data declarations, never imported constructors.
        if isinstance(node, ast.Attribute):
            root_key = self.qualified(name(node.value), file)
            global_info = self.raw_globals.get(root_key)
            if global_info and isinstance(global_info[1], ast.Call):
                typ = self.p.resolve_type(name(global_info[1].func), self.p.module(global_info[0]), global_info[0])
                field = self.p.type_fields(typ).get(node.attr)
                if field and field[1] and field[1].op == "const":
                    return field[1].value
        return None

    def link(self):
        for key, (file, node) in self.raw_globals.items():
            self.file = file
            if isinstance(node, ast.Call) and self.framework(node.func, {"FastAPI", "APIRouter"}):
                opts = {k.arg: k.value for k in node.keywords}
                prefix = self.constant(opts.get("prefix")) if "prefix" in opts else ""
                self.routers[key] = (prefix, self.dependencies(opts.get("dependencies")))
                if self.framework(node.func, {"FastAPI"}):
                    self.roots.add(key)
        for file, tree in self.trees.items():
            self.file = file
            def includes(nodes, conditional=False):
                for node in nodes:
                    if isinstance(node, ast.If):
                        test = self.constant(node.test)
                        if type(test) is bool:
                            yield from includes(node.body if test else node.orelse, conditional)
                        else:
                            yield from includes(node.body + node.orelse, True)
                    elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Call):
                        yield node.value, conditional
            for call, conditional in includes(tree.body):
                if isinstance(call.func, ast.Attribute) and call.func.attr == "include_router" and call.args:
                    opts = {k.arg: k.value for k in call.keywords}
                    prefix = self.constant(opts.get("prefix")) if "prefix" in opts else ""
                    self.mounts.append((self.qualified(name(call.func.value)), self.qualified(name(call.args[0])), prefix, self.dependencies(opts.get("dependencies")), conditional))
        def mounted(router, seen):
            if router in seen:
                return []
            prefix, deps = self.routers.get(router, ("", []))
            if prefix is None:
                return []
            result = [(prefix, deps, False)] if router in self.roots else []
            for parent, child, extra, outer, conditional in self.mounts:
                if child == router and extra is not None:
                    result.extend((path + extra + prefix, inherited + outer + deps, unknown or conditional) for path, inherited, unknown in mounted(parent, seen | {router}))
            return result
        for router, mid, path, verbs, status, deps in self.routes:
            mounts = mounted(router, set())
            if not mounts:
                self.p.warn("unmounted-router", "FastAPI router is not statically connected to an application", self.p.methods[mid].span, router)
            for prefix, outer_deps, conditional in mounts:
                for verb in verbs:
                    self.p.endpoints.append(Endpoint(mid, verb.upper(), prefix + path, self.p.methods[mid].module, "fastapi", status, outer_deps + deps, {"mount_unknown": conditional}))
        for info in self.p.types.values():
            if info.language == "python" and not info.table:
                for parent in info.parents:
                    resolved = self.p.resolve_type(parent, info.module, info.span.file)
                    if resolved and self.p.types[resolved].table:
                        info.table = self.p.types[resolved].table
        for _ in range(4):
            for info in self.p.types.values():
                if info.language == "python" and not info.annotations.get("model"):
                    info.annotations["model"] = any(self.p.types[parent].annotations.get("model") for p in info.parents
                                                    if (parent := self.p.resolve_type(p, info.module, info.span.file)))

    def expr(self, node):
        if node is None:
            return Expr("const", value=None)
        s = self.span(node)
        if isinstance(node, ast.Constant):
            if node.value is ...:
                return Expr("unknown", value="ellipsis", span=s)
            return Expr("const", value=node.value, span=s)
        if isinstance(node, ast.Name):
            return Expr("var", value=node.id, span=s, bindings=self.references(node))
        if isinstance(node, ast.Attribute):
            return Expr("field", (self.expr(node.value),), node.attr, s)
        if isinstance(node, ast.Call):
            receiver = self.expr(node.func.value) if isinstance(node.func, ast.Attribute) else None
            callee = node.func.attr if isinstance(node.func, ast.Attribute) else name(node.func)
            if any(k.arg is None for k in node.keywords):
                return Expr("unsupported", value="dynamic keyword expansion", span=s)
            return Expr("call", (receiver, tuple(self.expr(a) for a in node.args), tuple((k.arg, self.expr(k.value)) for k in node.keywords)), callee, s, bindings=self.references(node.func))
        if isinstance(node, ast.BinOp):
            return Expr("bin", (self.expr(node.left), self.expr(node.right)), self.operator(node.op), s)
        if isinstance(node, ast.BoolOp):
            return Expr("bool", tuple(self.expr(v) for v in node.values), "and" if isinstance(node.op, ast.And) else "or", s)
        if isinstance(node, ast.UnaryOp):
            return Expr("unary", (self.expr(node.operand),), {ast.Not: "not", ast.USub: "-", ast.UAdd: "+", ast.Invert: "~"}.get(type(node.op), "?"), s)
        if isinstance(node, ast.Compare):
            return Expr("compare", tuple(self.expr(v) for v in [node.left] + node.comparators), tuple(self.operator(op) for op in node.ops), s)
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            return Expr("list", tuple(self.expr(v) for v in node.elts), span=s)
        if isinstance(node, ast.Dict):
            if any(k is None for k in node.keys):
                return Expr("unsupported", value="dynamic dictionary expansion", span=s)
            return Expr("dict", tuple((self.expr(k), self.expr(v)) for k, v in zip(node.keys, node.values)), span=s)
        if isinstance(node, ast.Subscript):
            return Expr("index", (self.expr(node.value), self.expr(node.slice)), span=s)
        if isinstance(node, ast.Slice):
            return Expr("slice", tuple(self.expr(v) for v in [node.lower, node.upper, node.step]), span=s)
        if isinstance(node, ast.IfExp):
            return Expr("choose", (self.expr(node.test), self.expr(node.body), self.expr(node.orelse)), span=s)
        if isinstance(node, ast.Await):
            return Expr("await", (self.expr(node.value),), span=s)
        if isinstance(node, ast.JoinedStr):
            return Expr("format", tuple(self.expr(v.value) if isinstance(v, ast.FormattedValue) else self.expr(v) for v in node.values), span=s)
        if isinstance(node, ast.NamedExpr):
            return Expr("assign", (self.expr(node.target), self.expr(node.value)), span=s)
        return Expr("unsupported", value=type(node).__name__, span=s)

    @staticmethod
    def operator(op):
        return {ast.Add: "+", ast.Sub: "-", ast.Mult: "*", ast.Div: "/", ast.FloorDiv: "//", ast.Mod: "%", ast.Pow: "**",
                ast.Eq: "==", ast.NotEq: "!=", ast.Is: "is", ast.IsNot: "is not", ast.In: "in", ast.NotIn: "not in",
                ast.Gt: ">", ast.Lt: "<", ast.GtE: ">=", ast.LtE: "<=", ast.BitAnd: "&", ast.BitOr: "|", ast.BitXor: "^",
                ast.LShift: "<<", ast.RShift: ">>"}.get(type(op), "?")

    def block(self, nodes):
        return tuple(statement for node in nodes for statement in self.stmt(node))

    def stmt(self, node):
        s = self.span(node)
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            if node.value is None:
                return ()
            return (Stmt("assign", (tuple(self.expr(t) for t in targets), self.expr(node.value)), span=s),)
        if isinstance(node, ast.AugAssign):
            target = self.expr(node.target)
            return (Stmt("assign", ((target,), Expr("bin", (target, self.expr(node.value)), self.operator(node.op), s)), span=s),)
        if isinstance(node, ast.Expr):
            if isinstance(node.value, (ast.Yield, ast.YieldFrom)):
                return (Stmt("yield", (self.expr(node.value.value),), span=s),)
            return (Stmt("expr", (self.expr(node.value),), span=s),)
        if isinstance(node, ast.Return):
            return (Stmt("return", (self.expr(node.value),), span=s),)
        if isinstance(node, ast.Raise):
            return (Stmt("throw", (self.expr(node.exc),), span=s),)
        if isinstance(node, ast.If):
            return (Stmt("if", (self.expr(node.test),), self.block(node.body), self.block(node.orelse), span=s),)
        if isinstance(node, (ast.For, ast.AsyncFor)):
            return (Stmt("foreach", (self.expr(node.target), self.expr(node.iter)), self.block(node.body), self.block(node.orelse), span=s),)
        if isinstance(node, ast.While):
            return (Stmt("while", (self.expr(node.test),), self.block(node.body), self.block(node.orelse), span=s),)
        if isinstance(node, ast.Try):
            handlers = tuple((ast.unparse(h.type) if h.type else "*", h.name or "", self.block(h.body)) for h in node.handlers)
            return (Stmt("try", (handlers, self.block(node.finalbody)), self.block(node.body), self.block(node.orelse), span=s),)
        if isinstance(node, (ast.With, ast.AsyncWith)):
            contexts = tuple((self.expr(i.context_expr), self.expr(i.optional_vars) if i.optional_vars else None) for i in node.items)
            return (Stmt("with", contexts, self.block(node.body), span=s),)
        if isinstance(node, ast.Assert):
            return (Stmt("if", (Expr("unary", (self.expr(node.test),), "not", s),), (Stmt("throw", (Expr("new", value="AssertionError", span=s),), span=s),), span=s),)
        if isinstance(node, (ast.Break, ast.Continue)):
            return (Stmt(type(node).__name__.lower(), span=s),)
        if isinstance(node, ast.Global):
            return (Stmt("global", value=node.names, span=s),)
        if isinstance(node, ast.Pass):
            return ()
        return (Stmt("unsupported", value=type(node).__name__, span=s),)

    def lower(self, method, node):
        self.file = method.span.file
        if method.annotations.get("variadic"):
            return (Stmt("unsupported", value="variadic Python function", span=method.span),)
        return self.block(node.body)

"""Java syntax frontend and Spring fact provider. Execution belongs to the kernel."""
import json
import re

from tree_sitter import Language, Parser
import tree_sitter_java

from .ir import Endpoint, Expr, Method, Parameter, Span, Stmt, TypeInfo


def text(node):
    return node.text.decode("utf-8") if node is not None else ""


def walk(node):
    yield node
    for child in node.named_children:
        yield from walk(child)


def annotations(node):
    mods = next((c for c in node.named_children if c.type == "modifiers"), None)
    return {text(a.child_by_field_name("name")).split(".")[-1]: text(a.child_by_field_name("arguments"))
            for a in mods.named_children if a.type in {"annotation", "marker_annotation"}} if mods else {}


def annotation_value(raw, key=""):
    if key:
        match = re.search(r"\b" + re.escape(key) + r'\s*=\s*("(?:\\.|[^"\\])*")', raw)
    else:
        match = re.search(r'("(?:\\.|[^"\\])*")', raw)
    if match:
        try:
            return json.loads(match[1])
        except ValueError:
            pass
    return ""


def paths(raw):
    if not raw:
        return [""]
    value = re.search(r"(?:\b(?:value|path)\s*=\s*)(\{[^}]*\}|\"(?:\\.|[^\"\\])*\")", raw)
    if value:
        return [json.loads(s) for s in re.findall(r'"(?:\\.|[^"\\])*"', value[1])]
    prefix = raw.lstrip("( ")
    if prefix.startswith('"') or prefix.startswith("{"):
        head = re.match(r'(\{[^}]*\}|"(?:\\.|[^"\\])*")', prefix)
        return [json.loads(s) for s in re.findall(r'"(?:\\.|[^"\\])*"', head[1])] if head else []
    return [""]


class JavaAdapter:
    def __init__(self, project):
        self.p = project
        self.parser = Parser(Language(tree_sitter_java.language()))
        self.trees, self.raw_types = {}, {}
        self.file, self.local_types = "", {}

    def span(self, node):
        return Span(self.file, node.start_point.row + 1, node.start_point.column + 1)

    def index(self):
        for file, source in self.p.sources.items():
            if not file.endswith(".java"):
                continue
            self.file = file
            tree = self.parser.parse(source)
            self.trees[file] = tree
            if tree.root_node.has_error:
                self.p.warn("java-parse", "Java parser reported an unsupported or invalid construct", Span(file))
            package = next((text(n).removeprefix("package ").rstrip(";").strip() for n in tree.root_node.named_children if n.type == "package_declaration"), "")
            imported = self.p.imports.setdefault(file, {})
            for node in tree.root_node.named_children:
                if node.type == "import_declaration":
                    value = text(node).removeprefix("import ").removeprefix("static ").rstrip(";").strip()
                    if not value.endswith(".*"):
                        imported[value.split(".")[-1]] = value
            module = self.p.module(file)
            for node in walk(tree.root_node):
                if node.type not in {"class_declaration", "interface_declaration", "enum_declaration", "record_declaration"}:
                    continue
                short = text(node.child_by_field_name("name"))
                fqn = package + "." + short if package else short
                key = module + ":" + fqn
                parents = []
                for field in ["superclass", "interfaces"]:
                    raw = text(node.child_by_field_name(field))
                    raw = re.sub(r"^(?:extends|implements)\s+", "", raw)
                    parents.extend(re.findall(r"[\w.]+(?:\s*<[^>]+>)?", raw))
                if node.type == "interface_declaration":
                    ext = next((c for c in node.named_children if c.type == "extends_interfaces"), None)
                    if ext:
                        parents.extend(re.findall(r"[\w.]+(?:\s*<[^>]+>)?", re.sub(r"^extends\s+", "", text(ext))))
                meta = annotations(node)
                meta["kind"] = node.type
                info = TypeInfo(key, short, module, "java", self.span(node), parents=parents, annotations=meta)
                self.p.add_type(info)
                self.raw_types[key] = node
                body = node.child_by_field_name("body")
                for child in body.named_children if body else []:
                    if child.type == "field_declaration":
                        typ = text(child.child_by_field_name("type"))
                        ann = annotations(child)
                        modifiers = next((c for c in child.named_children if c.type == "modifiers"), None)
                        is_static = modifiers is not None and any(c.type == "static" for c in modifiers.children)
                        for var in child.named_children:
                            if var.type != "variable_declarator":
                                continue
                            field = text(var.child_by_field_name("name"))
                            default_node = var.child_by_field_name("value")
                            if is_static:
                                default = self.expr(default_node) if default_node else Expr("const", value=False if typ == "boolean" else 0 if typ in {"byte", "short", "int", "long", "float", "double"} else None, span=self.span(var), typ=typ)
                                self.p.globals[key + "." + field] = default
                                continue
                            info.fields[field] = (typ, self.expr(default_node) if default_node else None)
                            if "Column" in ann:
                                info.columns[field] = annotation_value(ann["Column"], "name") or field
                            if "Id" in ann:
                                info.primary_key = field
                            if "GeneratedValue" in ann:
                                info.generated_key = True
                            if set(ann) & {"Autowired", "Inject", "Resource"}:
                                info.annotations.setdefault("inject", []).append(field)
                    elif child.type in {"method_declaration", "constructor_declaration"}:
                        self.index_method(child, info)
                if "Table" in meta:
                    info.table = self.p.table_id(annotation_value(meta["Table"], "name") or short.lower())
                elif "Entity" in meta:
                    info.table = self.p.table_id(re.sub(r"(?<!^)(?=[A-Z])", "_", short).lower()) or self.p.table_id(short.lower())
                elif "Document" in meta:
                    info.table = self.p.table_id(annotation_value(meta["Document"], "collection") or short[:1].lower() + short[1:])
                for parent in parents:
                    match = re.search(r"(?:JpaRepository|CrudRepository|PagingAndSortingRepository|Repository)\s*<\s*([\w.]+)", parent)
                    if match:
                        info.repository_entity = match[1]

    def index_method(self, node, owner):
        name = "<init>" if node.type == "constructor_declaration" else text(node.child_by_field_name("name"))
        params = []
        raw_params = node.child_by_field_name("parameters")
        for par in raw_params.named_children if raw_params else []:
            if par.type not in {"formal_parameter", "spread_parameter"}:
                continue
            typ, pname = text(par.child_by_field_name("type")), text(par.child_by_field_name("name"))
            ann = annotations(par)
            location, alias, default = "", pname, None
            if "Param" in ann:
                alias = annotation_value(ann["Param"], "value") or annotation_value(ann["Param"]) or pname
            for attribute, loc in [("PathVariable", "path"), ("RequestParam", "query"), ("RequestHeader", "header"), ("RequestBody", "body")]:
                if attribute in ann:
                    location = loc
                    alias = annotation_value(ann[attribute], "name") or annotation_value(ann[attribute], "value") or annotation_value(ann[attribute]) or pname
                    value = annotation_value(ann[attribute], "defaultValue")
                    if value:
                        default = Expr("const", value=value, span=self.span(par))
            params.append(Parameter(pname, typ, location, alias, default))
        key = owner.key + "#" + name + "(" + ",".join(p.typ for p in params) + ")"
        ann = annotations(node)
        method = Method(key, name, owner.key, owner.module, "java", self.span(node), params,
                        text(node.child_by_field_name("type")), abstract=node.child_by_field_name("body") is None,
                        transaction="Transactional" in ann or "Transactional" in owner.annotations, annotations=ann)
        self.p.add_method(method, (node, node.start_point.row + 1, node.end_point.row + 1))
        owner.methods.append(key)
        # Constructor assignments are generic dependency wiring facts, not execution.
        if name == "<init>":
            names = {p.name for p in params}
            for assignment in walk(node):
                if assignment.type == "assignment_expression":
                    lhs, rhs = text(assignment.child_by_field_name("left")), text(assignment.child_by_field_name("right"))
                    if lhs.startswith("this.") and rhs in names:
                        owner.annotations.setdefault("inject", []).append(lhs[5:])

    def link(self):
        # Repository<Entity> can be declared by a derived Spring Data interface.
        for _ in range(4):
            for info in list(self.p.types.values()):
                if info.language != "java" or not info.repository_entity:
                    continue
                for parent in info.parents:
                    resolved = self.p.resolve_type(parent, info.module, info.span.file)
                    if resolved and not self.p.types[resolved].repository_entity:
                        self.p.types[resolved].repository_entity = info.repository_entity
        for info in self.p.types.values():
            if info.language != "java":
                continue
            if not set(info.annotations) & {"RestController", "Controller"}:
                continue
            enabled = self.p.enabled(info)
            if enabled is False:
                continue
            for mid in info.methods:
                method = self.p.methods[mid]
                ann = method.annotations
                if self.p.enabled(method) is False:
                    continue
                for attribute, args in ann.items():
                    if attribute not in {"RequestMapping", "GetMapping", "PostMapping", "PutMapping", "DeleteMapping", "PatchMapping"}:
                        continue
                    class_paths = paths(info.annotations.get("RequestMapping", ""))
                    verbs = re.findall(r"RequestMethod\.(\w+)", args) if attribute == "RequestMapping" else [attribute.removesuffix("Mapping").upper()]
                    verbs = verbs or ["*"]
                    for prefix in class_paths:
                        for suffix in paths(args):
                            path = "/" + "/".join(part.strip("/") for part in [prefix, suffix] if part.strip("/"))
                            for verb in verbs:
                                conditions = {"profile_unknown": enabled is None}
                                if re.search(r"\b(?:params|headers|consumes|produces)\s*=", args):
                                    conditions["mapping_constraints"] = args
                                self.p.endpoints.append(Endpoint(mid, verb, path, info.module, "spring", conditions=conditions))

    def expr(self, node):
        if node is None:
            return Expr("const", value=None)
        kind, raw, s = node.type, text(node), self.span(node)
        if kind in {"string_literal", "character_literal", "decimal_integer_literal", "hex_integer_literal", "octal_integer_literal", "binary_integer_literal", "decimal_floating_point_literal", "hex_floating_point_literal", "true", "false", "null_literal"}:
            try:
                if kind == "string_literal":
                    value, typ = json.loads(raw), "String"
                elif kind == "character_literal":
                    value, typ = json.loads('"' + raw[1:-1].replace('"', '\\"') + '"'), "char"
                elif kind in {"true", "false", "null_literal"}:
                    value, typ = {"true": True, "false": False, "null": None}[raw], "boolean" if raw != "null" else "null"
                elif "floating" in kind:
                    value, typ = float(raw.rstrip("dDfF").replace("_", "")), "double"
                else:
                    token = raw.rstrip("lL").replace("_", "")
                    base = 16 if token.lower().startswith("0x") else 2 if token.lower().startswith("0b") else 8 if len(token) > 1 and token.startswith("0") else 10
                    value, typ = int(token, base), "long" if raw[-1:] in "lL" else "int"
                return Expr("const", value=value, span=s, typ=typ)
            except ValueError:
                return Expr("unsupported", value="Java literal " + kind, span=s)
        if kind in {"identifier", "this", "super", "type_identifier", "scoped_type_identifier"}:
            return Expr("var", value=raw, span=s, typ=self.local_types.get(raw, ""))
        if kind == "field_access":
            owner, field = node.child_by_field_name("object"), text(node.child_by_field_name("field"))
            typ = "long" if text(owner) == "Long" and field in {"MAX_VALUE", "MIN_VALUE"} else "int" if text(owner) == "Integer" and field in {"MAX_VALUE", "MIN_VALUE"} else ""
            return Expr("field", (self.expr(owner),), field, s, typ)
        if kind == "method_invocation":
            obj = node.child_by_field_name("object")
            args = node.child_by_field_name("arguments")
            return Expr("call", (self.expr(obj) if obj else None, tuple(self.expr(a) for a in args.named_children) if args else (), ()), text(node.child_by_field_name("name")), s)
        if kind == "object_creation_expression":
            args = node.child_by_field_name("arguments")
            return Expr("new", tuple(self.expr(a) for a in args.named_children) if args else (), text(node.child_by_field_name("type")), s)
        if kind == "binary_expression":
            left, right = node.child_by_field_name("left"), node.child_by_field_name("right")
            op = text(node.child_by_field_name("operator")) or raw[left.end_byte - node.start_byte:right.start_byte - node.start_byte].strip()
            left_expr, right_expr = self.expr(left), self.expr(right)
            typ = "long" if "long" in {left_expr.typ, right_expr.typ} else "int" if "int" in {left_expr.typ, right_expr.typ} else ""
            return Expr("bool" if op in {"&&", "||"} else "bin", (left_expr, right_expr), {"&&": "and", "||": "or"}.get(op, op), s, typ)
        if kind == "unary_expression":
            operand = self.expr(node.child_by_field_name("operand") or node.named_children[-1])
            return Expr("unary", (operand,), text(node.child_by_field_name("operator")) or raw[0], s, operand.typ)
        if kind == "parenthesized_expression":
            return self.expr(node.named_children[0])
        if kind == "ternary_expression":
            return Expr("choose", tuple(self.expr(node.child_by_field_name(f)) for f in ["condition", "consequence", "alternative"]), span=s)
        if kind == "cast_expression":
            return Expr("cast", (self.expr(node.child_by_field_name("value")),), text(node.child_by_field_name("type")), s)
        if kind == "array_access":
            return Expr("index", (self.expr(node.child_by_field_name("array")), self.expr(node.child_by_field_name("index"))), span=s)
        if kind == "array_initializer":
            return Expr("list", tuple(self.expr(n) for n in node.named_children), span=s)
        if kind == "class_literal":
            return Expr("type", value=raw.removesuffix(".class"), span=s)
        if kind == "assignment_expression":
            left, right = self.expr(node.child_by_field_name("left")), self.expr(node.child_by_field_name("right"))
            op = text(node.child_by_field_name("operator"))
            if op != "=":
                right = Expr("bin", (left, right), op.removesuffix("="), s, left.typ)
            return Expr("assign", (left, right), span=s)
        if kind == "update_expression":
            target = self.expr(node.named_children[0])
            operation = "++" if "++" in raw else "--"
            return Expr("update", (target,), ("pre" if raw.startswith(operation) else "post") + operation, s, target.typ)
        if kind == "instanceof_expression":
            return Expr("instanceof", (self.expr(node.child_by_field_name("left")),), text(node.child_by_field_name("right")), s)
        return Expr("unsupported", value=kind, span=s)

    def block(self, node):
        if node is None:
            return ()
        if node.type in {"block", "constructor_body"}:
            return (Stmt("scope", body=tuple(s for child in node.named_children for s in self.stmt(child)), span=self.span(node)),)
        return self.stmt(node)

    def stmt(self, node):
        kind, s = node.type, self.span(node)
        if kind in {"block", "constructor_body"}:
            return self.block(node)
        if kind == "local_variable_declaration":
            typ = text(node.child_by_field_name("type"))
            result = []
            for var in node.named_children:
                if var.type == "variable_declarator":
                    pname = text(var.child_by_field_name("name"))
                    self.local_types[pname] = typ
                    value = self.expr(var.child_by_field_name("value")) if var.child_by_field_name("value") else Expr("unknown", value="uninitialized local", typ=typ, span=s)
                    result.append(Stmt("declare", ((Expr("var", value=pname, typ=typ, span=s),), value), value=typ, span=s))
            return tuple(result)
        if kind == "expression_statement":
            return (Stmt("expr", (self.expr(node.named_children[0]),), span=s),)
        if kind in {"return_statement", "throw_statement"}:
            return (Stmt("return" if kind == "return_statement" else "throw", (self.expr(node.named_children[0]) if node.named_children else Expr("const", value=None, span=s),), span=s),)
        if kind == "if_statement":
            return (Stmt("if", (self.expr(node.child_by_field_name("condition")),), self.block(node.child_by_field_name("consequence")), self.block(node.child_by_field_name("alternative")), span=s),)
        if kind in {"while_statement", "do_statement"}:
            return (Stmt("do" if kind == "do_statement" else "while", (self.expr(node.child_by_field_name("condition")),), self.block(node.child_by_field_name("body")), span=s),)
        if kind == "enhanced_for_statement":
            return (Stmt("foreach", (Expr("var", value=text(node.child_by_field_name("name")), span=s), self.expr(node.child_by_field_name("value"))), self.block(node.child_by_field_name("body")), span=s),)
        if kind == "for_statement":
            init = node.child_by_field_name("init")
            condition = self.expr(node.child_by_field_name("condition")) if node.child_by_field_name("condition") else Expr("const", value=True, span=s)
            updates = tuple(Stmt("expr", (self.expr(c),), span=self.span(c)) for c in node.children_by_field_name("update"))
            setup = self.stmt(init) if init and init.type == "local_variable_declaration" else (Stmt("expr", (self.expr(init),), span=s),) if init else ()
            return (Stmt("scope", body=setup + (Stmt("while", (condition,), self.block(node.child_by_field_name("body")), updates, value="for", span=s),), span=s),)
        if kind == "try_statement" or kind == "try_with_resources_statement":
            if kind == "try_with_resources_statement":
                return (Stmt("unsupported", value="Java try-with-resources", span=s),)
            handlers, final = [], ()
            for child in node.named_children:
                if child.type == "catch_clause":
                    parameter = next(c for c in child.named_children if c.type == "catch_formal_parameter")
                    pname = text(parameter.child_by_field_name("name"))
                    types = text(next((c for c in parameter.named_children if c.type == "catch_type"), None))
                    handlers.append((types, pname, self.block(child.child_by_field_name("body"))))
                elif child.type == "finally_clause":
                    final = self.block(child.named_children[-1])
            return (Stmt("try", (tuple(handlers), final), self.block(node.child_by_field_name("body")), span=s),)
        if kind in {"switch_expression", "switch_statement"}:
            groups = []
            block = node.child_by_field_name("body")
            for group in block.named_children if block else []:
                labels, body, default = [], [], False
                for child in group.named_children:
                    if child.type == "switch_label":
                        default = text(child).startswith("default")
                        labels.extend(self.expr(c) for c in child.named_children)
                    else:
                        body.extend(self.stmt(child))
                groups.append((tuple(labels), default, tuple(body), group.type == "switch_rule"))
            return (Stmt("switch", (self.expr(node.child_by_field_name("condition")), tuple(groups)), span=s),)
        if kind in {"break_statement", "continue_statement"}:
            return (Stmt("break" if kind.startswith("break") else "continue", span=s),)
        if kind in {"line_comment", "block_comment", "empty_statement"}:
            return ()
        return (Stmt("unsupported", value=kind, span=s),)

    def lower(self, method, node):
        self.file = method.span.file
        self.local_types = {p.name: p.typ for p in method.params}
        info = self.p.types.get(method.owner)
        if info:
            self.local_types.update({k: v[0] for k, v in self.p.type_fields(info.key).items()})
        return self.block(node.child_by_field_name("body"))
